function translateSource(source,language=locale){if(language==='uz')return source;const extra=window.BOZOR_EXTRA_COPY?.[language]?.[source];if(extra)return extra;const entry=window.BOZOR_COPY?.[source];if(entry)return entry[language==='ru'?0:1]||source;return language==='en'?source:undefined}
function localized(value,language=locale){const source=String(value??'');if(language==='uz')return source;const trimmed=source.trim(),start=source.indexOf(trimmed),lead=start<0?'':source.slice(0,start),tail=start<0?'':source.slice(start+trimmed.length),exact=translateSource(source,language)??translateSource(trimmed,language);if(exact!==undefined)return source===trimmed?exact:lead+exact+tail;const english=language!=='ru';let paymentNotice=trimmed.match(/^To‘lov: (.+)\. Sandbox natijasi real pul o‘tkazmasi emas\.$/);if(paymentNotice)return lead+(english?'Payment: ':'Оплата: ')+paymentNotice[1]+(english?'. Sandbox does not transfer real money.':'. Тестовый режим не переводит реальные деньги.')+tail;if(trimmed.includes(' · ')){const parts=trimmed.split(/( · )/g),mapped=parts.map(part=>{const piece=part.trim(),translated=translateSource(piece,language);if(translated!==undefined)return part===piece?translated:part.replace(piece,translated);const listingDate=piece.match(/^E’lon (.+)$/);if(listingDate)return part.replace('E’lon ',english?'Listing ':'Объявление ');const prefix=piece.match(/^(Sotuvchi:|Xaridor:)\s*(.*)$/);if(prefix){const label=prefix[1]==='Sotuvchi:'?(english?'Seller:':'Продавец:'):(english?'Buyer:':'Покупатель:');return part.replace(prefix[1],label)}const tailStatus=piece.match(/^(.*?)(Holat: tasdiqlanmagan)$/);if(tailStatus)return part.replace(tailStatus[2],english?'Status: unverified':'Статус: не подтверждён');return part});const joined=parts.map((_,i)=>mapped[i]).join('');if(joined!==trimmed)return lead+joined+tail}let prefixMatch=trimmed.match(/^(Yetkazish usuli:|To‘lov:)\s*(.*)$/);if(prefixMatch){const prefix=prefixMatch[1]==='To‘lov:'?(english?'Payment:':'Оплата:'):(english?'Delivery method:':'Способ доставки:');return lead+prefix+' '+prefixMatch[2]+tail}let dynamic=trimmed.match(/^Salom, (.+)$/);if(dynamic)return lead+(english?'Hello, ':'Здравствуйте, ')+dynamic[1]+tail;dynamic=trimmed.match(/^Buyurtma (.+)$/);if(dynamic)return lead+(english?'Order ':'Заказ ')+dynamic[1]+tail;dynamic=trimmed.match(/^Hozirda (\d+) ta ko‘rinadigan e’lon\.$/);if(dynamic)return lead+(english?`${dynamic[1]} listings available.`:`Доступно объявлений: ${dynamic[1]}.`)+tail;dynamic=trimmed.match(/^(\d+) yangi$/);if(dynamic)return lead+(english?`${dynamic[1]} new`:`${dynamic[1]} новых`)+tail;dynamic=trimmed.match(/^Talablar: (.+)$/);if(dynamic)return lead+(english?'Requirements: ':'Требования: ')+dynamic[1]+tail;dynamic=trimmed.match(/^Hisob (.+) sanasida yaratilgan\.$/);if(dynamic)return lead+(english?`Account created on ${dynamic[1]}.`:`Аккаунт создан ${dynamic[1]}.`)+tail;dynamic=trimmed.match(/^(\d+) dona$/);if(dynamic)return lead+(english?`${dynamic[1]} items`:`${dynamic[1]} шт.`)+tail;return english?source:source}
function localizeDOM(root=document.body){if(!root)return;const skip='.product-title,.detail-desc,.bubble,.conversation-item,.seller-mini,.product-cover strong,.cover-game,[data-user-content]';const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.data.trim()||node.parentElement?.closest(skip))continue;let rec=copyTextCache.get(node);if(!rec)rec={source:node.data,last:node.data};else if(node.data!==rec.last)rec={source:node.data,last:node.data};const next=localized(rec.source);if(next!==node.data)node.data=next;rec.last=next;copyTextCache.set(node,rec)}for(const el of $$('[placeholder],[aria-label],[title],[alt]',root)){if(el.closest(skip))continue;let rec=copyAttrCache.get(el)||{};for(const attr of ['placeholder','aria-label','title','alt']){if(!el.hasAttribute(attr))continue;const value=el.getAttribute(attr);if(!rec[attr]||value!==rec[attr].last)rec[attr]={source:value,last:value};const next=localized(rec[attr].source);if(next!==value)el.setAttribute(attr,next);rec[attr].last=next}copyAttrCache.set(el,rec)}document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';syncLanguageMenu()}
let localizeQueued=false;new MutationObserver(()=>{if(localizeQueued)return;localizeQueued=true;requestAnimationFrame(()=>{localizeQueued=false;localizeDOM()})}).observe(document.body,{childList:true,subtree:true});
function esc(x=''){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function icon(name,extra=''){return `<svg class="icon ${extra}" aria-hidden="true"><use href="#i-${name}"></use></svg>`}
function fieldIconName(control){const name=(control.name||'').toLowerCase(),type=(control.type||'').toLowerCase(),hint=`${name} ${control.autocomplete||''} ${control.placeholder||''}`.toLowerCase();if(type==='hidden'||['checkbox','radio','submit','button','file','email','password'].includes(type)||/email|mail|password|passcode|token|secret/.test(hint))return '';if(/game|platform/.test(hint))return 'gamepad';if(/category|genre|tag/.test(hint))return 'layers';if(/delivery_method/.test(name))return 'cart';if(/delivery_eta|date|time|eta/.test(hint))return 'clock';if(/title|slug|post|listing/.test(hint))return 'file-text';if(/description|message|comment|body|bio|requirement|resolution|delivery/.test(hint)||control.tagName==='TEXTAREA')return 'message';if(/price|amount|budget|commission|currency|wallet|payout/.test(hint))return 'wallet';if(/stock|quantity|count|item/.test(hint))return 'box';if(/region|country|language|locale|server/.test(hint))return 'globe';if(/rank|rating|review/.test(hint))return 'star';if(/photo|image|upload|file/.test(hint))return 'upload';if(/search|query|\bq\b/.test(hint)||type==='search')return 'search';if(/name|user|seller|buyer|account/.test(hint)||control.autocomplete==='name')return 'user';if(type==='number')return 'settings';if(control.tagName==='SELECT')return 'layers';return 'file-text'}
function decorateFieldControl(label,control){label.querySelectorAll('.field-icon').forEach(node=>node.remove());const name=fieldIconName(control);let wrap=control.parentElement?.classList.contains('field-control')?control.parentElement:null;if(!name){if(wrap){wrap.querySelectorAll(':scope > .field-control-icon').forEach(node=>node.remove());wrap.classList.remove('has-icon');delete wrap.dataset.controlKind;if(!wrap.classList.contains('auth-password-control')){wrap.before(control);wrap.remove()}}return}if(!wrap){wrap=document.createElement('div');wrap.className='field-control';control.before(wrap);wrap.append(control)}wrap.classList.add('has-icon');wrap.dataset.controlKind=control.tagName==='SELECT'?'select':control.tagName==='TEXTAREA'?'multiline':'input';if(!wrap.querySelector(':scope > .field-control-icon'))wrap.insertAdjacentHTML('afterbegin',icon(name,'field-control-icon'))}
