 const menuRow=(href,iconName,title,description)=>`<a class="profile-menu-row" href="${href}"><span class="profile-menu-icon">${icon(iconName)}</span><span class="profile-menu-copy"><b>${title}</b><small>${description}</small></span></a>`;
