async function renderSeller(){if(!me){location.hash='login';return}if(!me.email_verified){app.innerHTML=`<section class="page">${pageTitle(adminText('Sotuvchi bo‘lish','Стать продавцом','Become a seller'))}<div class="notice warn">${adminText('Sotuvchi profilini yoqishdan oldin email tasdiqlanishi kerak.','Подтвердите email перед созданием профиля продавца.','Verify your email before creating a seller profile.')}</div></section>`;return}if(!me.seller){app.innerHTML=`<section class="page">${pageTitle(adminText('Sotuvchi profilini yoqish','Активировать профиль продавца','Enable seller profile'),adminText('Bitta hisob xaridor va sotuvchi vazifalarini bajarishi mumkin.','Один аккаунт может быть и покупателем, и продавцом.','One account can act as both a buyer and a seller.'))}<div class="form-card"><div class="notice">${adminText('Sotuvchi profilini yarating. Keyingi bosqichda email va Didit orqali shaxsni tekshirasiz; pasport rasmi SentryLoot serveriga yuklanmaydi.','Создайте профиль продавца. На следующем этапе подтвердите email и личность через Didit; фото паспорта не загружается на сервер SentryLoot.','Create your seller profile. In the next step, verify your email and identity with Didit; passport images are not uploaded to SentryLoot.')}</div><form id="seller-form"><div class="field"><label>${adminText('Do‘kon nomi','Название магазина','Shop name')}</label><input name="shop_name" maxlength="80" required></div><div class="field"><label>${adminText('Qisqacha tavsif','Краткое описание','Short description')}</label><textarea name="bio" maxlength="1000"></textarea></div><button class="button-primary">${adminText('Sotuvchi profilini yaratish','Создать профиль продавца','Create seller profile')}</button></form></div></section>`;return}
 if(me.seller.identity_status!=='verified')return renderSellerIdentity();
 if(me.seller.verification_status!=='verified'||!me.seller.selling_enabled){const state=me.seller.verification_status||'pending';const sellerState=state==='pending'?adminText('Ko‘rib chiqilmoqda','На проверке','In review'):state==='rejected'?adminText('Rad etildi','Отклонено','Rejected'):state==='verified'?adminText('Tasdiqlandi','Подтверждено','Verified'):state;app.innerHTML=`<section class="page">${pageTitle(adminText('Sotuvchi tekshiruvi','Проверка продавца','Seller verification'),esc(me.seller.shop_name))}<div class="form-card"><div class="notice warn"><b>${adminText('Holat:','Статус:','Status:')} ${esc(sellerState)}</b><br>${adminText('Sotish, buyurtma yetkazish va payout so‘rash profil tekshirilib tasdiqlangandan keyin ochiladi. Didit shaxsni tasdiqladi. Sotish administrator ushbu profilni alohida tasdiqlagach yoqiladi.','Продажа, доставка заказов и запрос выплат станут доступны после проверки и подтверждения профиля. Didit подтвердил личность. Продажи включит администратор после отдельного одобрения профиля.','Selling, order delivery, and payout requests will unlock after the profile is reviewed and approved. Didit has verified your identity. An administrator must approve this profile separately before selling is enabled.')}</div><form id="seller-form"><div class="field"><label>${adminText('Do‘kon nomi','Название магазина','Shop name')}</label><input name="shop_name" value="${esc(me.seller.shop_name)}" maxlength="80" required></div><div class="field"><label>${adminText('Qisqacha tavsif','Краткое описание','Short description')}</label><textarea name="bio" maxlength="1000">${esc(me.seller.bio||'')}</textarea></div><button class="button-primary" ${state==='pending'?'disabled':''}>${state==='pending'?adminText('Tekshiruv kutilmoqda','Проверка ожидается','Review pending'):adminText('Tekshiruvga yuborish','Отправить на проверку','Submit for review')}</button></form></div></section>`;return}
 const [summary,games,cats]=await Promise.all([api('/seller/summary'),api('/games'),api('/categories')]);await loadWalletFx();app.innerHTML=`<section class="page">${pageTitle('Sotuvchi paneli',esc(me.seller.shop_name)+' · Holat: tasdiqlangan','<a class="button-primary" href="#orders">Buyurtmalar</a>' )}<div class="stats"><div class="stat"><small>E’lonlar</small><b>${summary.listings.reduce((a,x)=>a+x.count,0)}</b></div><div class="stat"><small>Buyurtmalar</small><b>${summary.orders.reduce((a,x)=>a+x.count,0)}</b></div><div class="stat"><small>Yechish mumkin</small><b>${walletAmount(summary.wallet.available_minor,summary.wallet.currency)}</b></div><div class="stat"><small>Escrow’da ushlangan</small><b>${walletAmount(summary.wallet.held_minor,summary.wallet.currency)}</b></div></div><div class="notice warn">${adminText('Balans tanlangan valyutada kunlik ma’lumot kursi bilan taxminiy ko‘rsatiladi; hisob-kitob UZS’da qoladi. Escrow’dagi summa xaridor buyurtmani tasdiqlaguncha yechilmaydi.','Баланс приблизительно пересчитан по справочному дневному курсу; учёт ведётся в UZS. Средства в escrow нельзя вывести, пока покупатель не подтвердит заказ.','Balances are approximate conversions using a daily reference rate; the ledger remains in UZS. Escrow funds stay held until the buyer confirms the order.')} “Yechish mumkin” balansi ham hozircha sinov hisobidir: real bank, elektron hamyon yoki kripto to‘lovi yoqilmagan.</div><div class="detail-grid">${sellerListingFormMarkup(games,cats)}<div><div class="panel seller-listings-panel"><h3>E’lonlarim</h3><div id="my-listings" class="help">Yuklanmoqda…</div></div></div></div></section>`;
 setupListingImagePreviews(app);setupListingFilePreviews(app);setupListingWizard(app);const gameInput=$('#listing-form [name=game_name]'),gameFields=$('[data-game-specific-fields]');const syncGameFields=()=>{if(gameFields)gameFields.innerHTML=gameSpecificFieldsMarkup(gameInput?.value)};gameInput?.addEventListener('input',syncGameFields);gameInput?.addEventListener('change',syncGameFields);syncGameFields();const accountCategory=$('#listing-form [name=category_id]'),accountNotice=$('[data-account-sale-attestation]'),accountConsent=$('#listing-form [name=accept_account_terms]');const syncAccountNotice=()=>{const isAccount=accountCategory?.selectedOptions[0]?.dataset.productType==='account';if(accountNotice)accountNotice.hidden=!isAccount||Boolean(accountConsent?.checked);if(accountConsent)accountConsent.required=isAccount};accountCategory?.addEventListener('change',syncAccountNotice);accountConsent?.addEventListener('change',syncAccountNotice);syncAccountNotice();$('#listing-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,formData=new FormData(f),d=Object.fromEntries(formData);d.accept_account_terms=formData.has('accept_account_terms');const photoFiles=formData.getAll('listing_photos').filter(file=>file instanceof File&&file.size);delete d.listing_photos;d.linked_accounts=formData.getAll('linked_accounts');d.price_minor=Number(d.price_minor);d.stock=Number(d.stock);d.attributes={rank:d.rank};delete d.rank;for(const [key,value] of formData.entries())if(key.startsWith('game_attr_')&&String(value).trim())d.attributes[key.slice(10)]=String(value).trim();d.submit_for_review=true;try{const uploaded=[];for(const [index,file] of photoFiles.entries()){toast(adminText(`Rasm yuklanmoqda (${index+1}/${photoFiles.length})`,`Загрузка фото (${index+1}/${photoFiles.length})`,`Uploading photo (${index+1}/${photoFiles.length})`));uploaded.push(await uploadListingPhoto(file))}d.images=uploaded;const x=await api('/listings',{method:'POST',body:JSON.stringify(d)});location.hash='listing-review/'+encodeURIComponent(x.id)}catch(err){toast(err.message)}};
 const own=await api('/seller/listings');$('#my-listings').innerHTML=own.length?own.map(l=>`<div class="order-line"><div class="order-head"><b>${esc(l.title)}</b>${status(l.status==='published'&&l.marketplace_visible===false?'not_public':l.status)}</div><p class="help">${fmt(l.price_minor,l.currency)} · ${esc(l.moderation_note||'')}</p>${l.status==='published'&&l.marketplace_visible===false?`<div class="notice warn">${adminText('E’lon hisobingizda faol, ammo hozir ommaviy bozorda ko‘rinmaydi: savdo rejimi, o‘yin tasdig‘i yoki mahsulot qoldig‘i talabi bajarilmagan.','Объявление активно в кабинете, но не отображается на публичном рынке: не выполнены условия режима торговли, допуска игры или наличия товара.','Your listing is active in your account but hidden from the public marketplace because the sales mode, game approval, or available stock requirement is not met.')}</div>`:''}<div class="queue-actions">${['draft','rejected','paused'].includes(l.status)?`<button class="button-secondary" data-action="submit-listing" data-id="${esc(l.id)}">Tekshiruvga yuborish</button>`:''}${l.status==='published'?`<button class="button-secondary" data-action="pause-listing" data-id="${esc(l.id)}">Vaqtincha yashirish</button>`:''}${l.status==='paused'?`<button class="button-secondary" data-action="resume-listing" data-id="${esc(l.id)}">Qayta yuborish</button>`:''}${['draft','rejected','paused'].includes(l.status)?`<button class="button-danger" data-action="archive-listing" data-id="${esc(l.id)}">Arxivlash</button>`:''}</div><details style="margin-top:10px"><summary class="text-link">E’lonni tahrirlash</summary>${listingEditFormMarkup(l)}</details></div>`).join(''):empty('Hozircha e’lon yo‘q.')}
async function renderRequests(){const [rows,mine,games,cats]=await Promise.all([api('/requests'),me?api('/requests?mine=1'):Promise.resolve([]),api('/games'),api('/categories')]);const replies=await Promise.all(mine.map(async r=>[r.id,await api('/requests/'+encodeURIComponent(r.id)+'/responses').catch(()=>[])]));const byId=Object.fromEntries(replies);app.innerHTML=`<section class="page">${pageTitle('Mahsulot so‘rovlari','Bozorda yo‘q mahsulotni so‘rang yoki ochiq talablarni ko‘rib chiqing.')}<div class="detail-grid"><div><div class="panel"><h2>Ochiq so‘rovlar</h2>${rows.length?rows.map(r=>`<div class="order-line"><div class="order-head"><div><h3>${esc(r.title)}</h3><div class="help">${esc(r.game_name)} · ${esc(r.requester)} · ${new Date(r.created_at+'Z').toLocaleDateString(localeTag())}</div></div>${r.budget_minor?`<b>${fmt(r.budget_minor,r.currency)}</b>`:''}</div><p class="detail-desc">${esc(r.description)}</p>${me?.seller&&!r.is_own?`<button class="button-secondary" data-action="respond-request" data-id="${esc(r.id)}">Javob berish</button><form data-form="request-response" data-request="${esc(r.id)}" hidden><div class="field"><label>Taklifingiz</label><textarea name="message" required minlength="2" maxlength="2000" placeholder="Mahsulot, narx yoki muddat bo‘yicha taklif yozing"></textarea></div><div class="actions"><button class="button-primary">Javob yuborish</button><button type="button" class="button-secondary" data-action="cancel-request-response">Bekor qilish</button></div></form>`:''}</div>`).join(''):empty('Hozircha ochiq so‘rovlar yo‘q.')}</div>${mine.length?`<div class="panel" style="margin-top:14px"><h2>So‘rovlarim va sotuvchilar javoblari</h2>${mine.map(r=>`<div class="order-line"><b>${esc(r.title)}</b> ${status(r.status)}<p class="help">${esc(r.description)}</p>${(byId[r.id]||[]).map(a=>`<div class="notice"><b>${esc(a.seller_name)}</b><p>${esc(a.message)}</p>${a.listing_id?`<a class="text-link" href="/listing/${encodeURIComponent(a.listing_id)}">E’lonni ko‘rish →</a>`:''}<div class="actions"><button class="button-secondary" data-action="contact-request" data-id="${esc(r.id)}" data-seller="${esc(a.seller_id)}">Sotuvchi bilan suhbat</button></div></div>`).join('')||'<p class="help">Sotuvchilardan javob kutilmoqda.</p>'}</div>`).join('')}</div>`:''}</div><div class="form-card"><h2>So‘rov yuborish</h2>${me?`<form id="request-form"><div class="field"><label>O‘yin</label><select name="game_id">${games.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label>Kategoriya</label><select name="category_id"><option value="">Ixtiyoriy</option>${cats.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Sarlavha</label><input name="title" required minlength="5" maxlength="120"></div><div class="field"><label>Tavsif</label><textarea name="description" required minlength="10" maxlength="3000"></textarea></div><div class="field"><label>Maqsad budjeti (UZS)</label><input type="number" min="1" name="budget_minor"></div><button class="button-primary">So‘rov yaratish</button></form>`:'<div class="notice">So‘rov yuborish uchun <a class="text-link" href="#login">tizimga kiring</a>.</div>'}</div></div></section>`;if($('#request-form'))$('#request-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget));if(d.budget_minor)d.budget_minor=Number(d.budget_minor);if(!d.category_id)delete d.category_id;try{await api('/requests',{method:'POST',body:JSON.stringify(d)});toast('So‘rov yaratildi');renderRequests()}catch(x){toast(x.message)}}}
async function renderMessages(id=selectedConversation){if(!me){location.hash='login';return}const rows=await api('/conversations');if(!id&&rows.length)id=rows[0].id;selectedConversation=id||'';let convo=id?await api('/conversations/'+id):null;app.innerHTML=`<section class="page">${pageTitle('Xabarlar','Sotuvchi va xaridor o‘rtasidagi suhbatlar.')}<div class="message-layout"><div class="conversation-list">${rows.map(c=>`<a class="conversation-item ${c.id===id?'active':''}" href="#conversation/${encodeURIComponent(c.id)}"><b>${esc(c.other_name)}</b><p>${esc(c.last_message||c.listing_title||'Yangi suhbat')}</p>${c.unread?`<span class="status">${c.unread} yangi</span>`:''}</a>`).join('')||'<div class="help" style="padding:14px">Suhbatlar yo‘q. E’lon ichidan sotuvchiga yozing.</div>'}</div><div class="chat">${convo?`<div class="chat-messages">${convo.messages.map(m=>`<div class="bubble ${m.sender_id===me.id?'mine':''}">${esc(m.body)}<div class="help">${new Date(m.created_at+'Z').toLocaleString(localeTag())}</div></div>`).join('')||'<p class="help">Suhbat boshlandi. Xabar yuboring.</p>'}</div><form class="chat-form" id="message-form"><input name="body" maxlength="2000" required placeholder="Xabar yozing…"><button class="button-primary">Yuborish</button></form>`:'<div class="loading">Suhbatni tanlang</div>'}</div></div></section>`;if($('#message-form'))$('#message-form').onsubmit=async e=>{e.preventDefault();const body=new FormData(e.currentTarget).get('body');try{await api('/conversations/'+id+'/messages',{method:'POST',body:JSON.stringify({body})});renderMessages(id)}catch(x){toast(x.message)}}}
async function renderFavorites(){if(!me){location.hash='login';return}const xs=await api('/favorites');app.innerHTML=`<section class="page">${pageTitle('Saqlangan e’lonlar')}${xs.length?`<div class="product-grid">${xs.map(card).join('')}</div>`:empty('Saqlangan e’lon yo‘q.')}</section>`}
function sellerGateNotice(){return `<div class="notice warn">${me.seller?.identity_status!=='verified'?adminText('Balans va payout so‘rash uchun sotuvchi Didit tekshiruvi va administrator tasdig‘idan o‘tishi kerak.','Чтобы открыть баланс и выплаты, продавец должен пройти Didit и получить подтверждение администратора.','Seller balance and payout access require Didit verification and administrator approval.'):adminText('Profil tekshiruvi tugamaguncha balans va payout amallari yopiq.','Баланс и выплаты закрыты до завершения проверки профиля.','Wallet and payout actions stay closed until the seller review is complete.')}</div>`}
function renderWalletCards(wallet){return `<div class="wallet-grid"><article class="wallet-balance-card"><span>${icon('wallet')}</span><small>${adminText('YECHISH MUMKIN','ДОСТУПНО К ВЫВОДУ','AVAILABLE')}</small><b>${walletAmount(wallet.available_minor,wallet.currency)}</b><p>${adminText('Buyurtmalar yakunlangach mavjud bo‘ladi.','Доступно после завершения заказов.','Available after orders are completed.')}</p></article><article class="wallet-stat-card"><small>${adminText('Escrow’da ushlangan','Удерживается в escrow','Held in escrow')}</small><b>${walletAmount(wallet.held_minor,wallet.currency)}</b><p>${adminText('Xaridor buyurtmani yakunlashini kutmoqda.','Ожидает завершения заказа покупателем.','Waiting for buyer order completion.')}</p></article><article class="wallet-stat-card"><small>${adminText('Payout so‘rovida','Ожидает выплаты','Payout pending')}</small><b>${walletAmount(wallet.pending_payout_minor,wallet.currency)}</b><p>${adminText('So‘rov ko‘rib chiqilmoqda.','Запрос рассматривается.','Request is being reviewed.')}</p></article><article class="wallet-stat-card"><small>${adminText('Tashqi o‘tkazma qaydi','Записано как выплаченное','Recorded as paid out')}</small><b>${walletAmount(wallet.paid_out_minor,wallet.currency)}</b><p>${adminText('Platforma pulni o‘zi yubormaydi.','Платформа сама не переводит деньги.','The platform does not send money itself.')}</p></article></div>`}
async function renderWallet(){if(!me){location.hash='login';return}await loadWalletFx();if(!me.seller||me.seller.identity_status!=='verified'||!me.seller.selling_enabled){app.innerHTML=`<section class="page">${pageTitle(adminText('Wallet balance','Баланс кошелька','Wallet balance'),adminText('Sotuvlardan tushgan mablag‘lar holati.','Статус средств от продаж.','Track funds earned from sales.'))}<div class="wallet-grid"><article class="wallet-balance-card"><span>${icon('wallet')}</span><small>${adminText('MAVJUD BALANS','ДОСТУПНЫЙ БАЛАНС','AVAILABLE BALANCE')}</small><b>${walletAmount(0,'UZS')}</b><p>${adminText('Tasdiqlangan sotuvchi balansiga hali mablag‘ tushmagan.','На баланс подтверждённого продавца пока не поступали средства.','No funds have reached an approved seller wallet yet.')}</p></article></div>${sellerGateNotice()}<a class="button-primary" href="#seller">${adminText('Sotuvchi tekshiruviga o‘tish','Перейти к проверке продавца','Continue seller verification')}</a></section>`;return}const summary=await api('/seller/summary');app.innerHTML=`<section class="page">${pageTitle(adminText('Wallet balance','Баланс кошелька','Wallet balance'),adminText('Sotuvlardan tushgan mablag‘lar aniq holati.','Точный статус средств от продаж.','A clear breakdown of sales funds.'))}<div class="notice warn">${adminText('Bu ichki sandbox hisobi. Tanlangan valyutadagi qiymat kunlik ma’lumot kursi bo‘yicha taxminiy; hisob-kitob UZS’da qoladi. Real pul o‘tkazilmaydi.','Это внутренний sandbox-счёт. Значение в выбранной валюте приблизительное и рассчитано по справочному дневному курсу; учёт ведётся в UZS. Реальные переводы не выполняются.','This is an internal sandbox ledger. The selected-currency value is an estimate from the daily reference rate; the ledger remains in UZS. No real transfer is made.')}</div>${renderWalletCards(summary.wallet)}<div class="wallet-actions"><a class="button-primary" href="#payout-options">${adminText('Payout options','Способы вывода','Payout options')}</a><a class="button-secondary" href="#orders">${adminText('Buyurtmalarni ko‘rish','Посмотреть заказы','View orders')}</a></div></section>`}
async function renderPayoutOptions(){if(!me){location.hash='login';return}await loadWalletFx();if(!me.seller||me.seller.identity_status!=='verified'||!me.seller.selling_enabled){app.innerHTML=`<section class="page">${pageTitle(adminText('Payout options','Способы вывода','Payout options'),adminText('Balansdan mablag‘ yechish sozlamalari.','Настройки вывода средств с баланса.','Withdrawal settings for your seller balance.'))}${sellerGateNotice()}<a class="button-primary" href="#seller">${adminText('Sotuvchi tekshiruviga o‘tish','Перейти к проверке продавца','Continue seller verification')}</a></section>`;return}const [summary,history]=await Promise.all([api('/seller/summary'),api('/payouts')]);const w=summary.wallet;app.innerHTML=`<section class="page">${pageTitle(adminText('Payout options','Способы вывода','Payout options'),adminText('Balansdan mablag‘ yechish holati va usullari.','Статус и способы вывода средств.','Withdrawal status and available methods.'))}<div class="wallet-inline-balance"><span>${adminText('Yechish mumkin','Доступно к выводу','Available to withdraw')}</span><b>${walletAmount(w.available_minor,w.currency)}</b><a href="#wallet">${adminText('Wallet tafsilotlari','Детали кошелька','Wallet details')}</a></div><div class="notice warn">${adminText('To‘lov provayderi ulanmagan. Bank/karta, elektron hamyon va kripto yechimi hozircha haqiqiy o‘tkazma qilmaydi. Moliyaviy ma’lumot kiritish o‘chirilgan.','Платёжный провайдер не подключён. Банковские карты, электронные кошельки и криптовалюта пока не выполняют реальные переводы. Ввод платёжных данных отключён.','No payout provider is connected. Cards, e-wallets, and crypto do not make real transfers. Payment details cannot be entered.')}</div><div class="payout-method-grid"><article class="payout-method-card"><span>${icon('cart')}</span><div><b>${adminText('Bank karta / hisob','Банковская карта / счёт','Bank card / account')}</b><small>${adminText('Provayder sozlangach ochiladi','Будет доступно после настройки провайдера','Available after provider setup')}</small></div><span class="status paused">${adminText('Tez orada','Скоро','Coming later')}</span></article><article class="payout-method-card"><span>${icon('globe')}</span><div><b>${adminText('Elektron hamyon','Электронный кошелёк','E-wallet')}</b><small>${adminText('Provayder sozlangach ochiladi','Будет доступно после настройки провайдера','Available after provider setup')}</small></div><span class="status paused">${adminText('Tez orada','Скоро','Coming later')}</span></article><article class="payout-method-card"><span>${icon('shield')}</span><div><b>${adminText('Kripto hamyon','Криптокошелёк','Crypto wallet')}</b><small>${adminText('Huquqiy va provayder tekshiruvidan keyin','После правовой проверки и подключения провайдера','After legal review and provider setup')}</small></div><span class="status paused">${adminText('O‘chiq','Отключено','Disabled')}</span></article></div><div class="panel"><h2>${adminText('Payout tarixi','История выплат','Payout history')}</h2>${history.length?history.map(p=>`<div class="order-line"><div class="order-head"><b>${walletAmount(p.amount_minor,p.currency)}</b>${status(p.status)}</div><small class="help">${new Date(p.created_at+'Z').toLocaleDateString(localeTag())} · ${esc(p.note||adminText('Ko‘rib chiqilmoqda','На рассмотрении','Under review'))}</small></div>`).join(''):empty(adminText('Hozircha payout so‘rovi yo‘q.','Запросов на выплату пока нет.','No payout requests yet.'))}</div></section>`}
async function renderMyReviews(){if(!me){location.hash='login';return}const rows=await api('/reviews/mine');app.innerHTML=`<section class="page">${pageTitle(adminText('Sharhlarim','Мои отзывы','My reviews'),adminText('Faqat yakunlangan xaridlaringiz uchun yozilgan sharhlar.','Отзывы только по завершённым покупкам.','Reviews you wrote for completed purchases.'))}<div class="review-list">${rows.length?rows.map(r=>`<article class="panel review-card"><div class="order-head"><div><a class="review-listing-link" href="/listing/${encodeURIComponent(r.listing_id)}">${esc(r.listing_title)}</a><small class="help">${adminText('Sotuvchi','Продавец','Seller')}: ${esc(r.seller_name)} · ${esc(r.order_reference)}</small></div><span class="review-stars" aria-label="${r.rating} / 5">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p>${esc(r.body)}</p><time class="help">${new Date(r.created_at+'Z').toLocaleDateString(localeTag())}</time></article>`).join(''):empty(adminText('Hozircha sharh yozmagansiz. Tugallangan xariddan so‘ng buyurtma sahifasida baho qoldirishingiz mumkin.','Вы пока не оставляли отзывов. После завершения покупки можно оценить её на странице заказа.','You have not written a review yet. After a purchase is completed, leave a rating on its order page.'),`<a class="button-secondary" href="#orders">${adminText('Buyurtmalarim','Мои заказы','My orders')}</a>`)}</div></section>`}
const HELP_ARTICLES=[
 {category:'orders',title:['Buyurtma va yetkazish','Заказ и доставка','Orders and delivery'],body:['To‘lov tasdiqlangach, sotuvchi buyurtma ichidan mahsulotni yuboradi. Yetkazishni tekshirib bo‘lmaguncha buyurtmani yakunlamang. Muammo bo‘lsa, buyurtma sahifasidan nizo oching.','После подтверждения оплаты продавец отправит товар в заказе. Не завершайте заказ, пока не проверили доставку. Если возникла проблема, откройте спор на странице заказа.','After payment confirmation, the seller delivers through the order page. Do not complete an order until you have checked delivery. Open a dispute from the order page if something is wrong.']},
 {category:'wallet',title:['Wallet balance va payout','Баланс и выплаты','Wallet balance and payouts'],body:['Wallet sotuvchining ichki hisobini ko‘rsatadi: yechish mumkin, escrow’da ushlangan va payout so‘rovidagi summa. Hozirgi versiya sandbox; karta, elektron hamyon yoki kriptoga real pul yubormaydi.','Кошелёк показывает внутренний баланс продавца: доступные средства, escrow и ожидающие выплаты. Сейчас это sandbox; реальные переводы на карту, кошелёк или криптоадрес не выполняются.','The wallet shows a seller’s internal balance: available funds, escrow holds, and pending payouts. This version is sandbox only and sends no real money to a card, e-wallet, or crypto address.']},
 {category:'account',title:['Sotuvchi tekshiruvi','Проверка продавца','Seller verification'],body:['Sotish uchun tasdiqlangan email, Didit shaxs tekshiruvi va administrator ko‘rigi kerak. Pasport yoki yuz tasvirini xabarlarga yubormang; tekshiruv Didit ichida amalga oshadi.','Для продаж нужны подтверждённая почта, проверка личности в Didit и одобрение администратора. Не отправляйте паспорт или фото лица в сообщениях.','Selling requires a verified email, Didit identity verification, and administrator approval. Do not send passport or face images in messages.']},
 {category:'safety',title:['Hisobni xavfsiz saqlash','Безопасность аккаунта','Keep your account safe'],body:['Hech kimga parol, bir martalik kod yoki tiklash havolasini bermang. Platforma ichidagi himoyalangan buyurtma oqimidan foydalaning va shubhali e’lonlar haqida xabar bering.','Никому не сообщайте пароль, одноразовый код или ссылку восстановления. Используйте защищённый процесс заказа на платформе и сообщайте о подозрительных объявлениях.','Never share your password, one-time codes, or reset links. Use the protected order flow and report suspicious listings.']}
];
function helpText(row){return row[locale==='ru'?1:locale==='uz'?0:2]}
async function renderHelpCenter(){const lang=locale==='ru'?1:locale==='uz'?0:2;app.innerHTML=`<section class="page">${pageTitle(adminText('Yordam markazi','Центр помощи','Help center'),adminText('Buyurtmalar, wallet va hisob xavfsizligi bo‘yicha qisqa javoblar.','Ответы о заказах, кошельке и безопасности аккаунта.','Quick answers about orders, wallet, and account safety.'))}<div class="help-center-hero"><label class="sr-only" for="help-search">${adminText('Yordamdan qidirish','Поиск в центре помощи','Search help')}</label><input id="help-search" type="search" placeholder="${adminText('Savol yoki mavzu bo‘yicha qidiring','Поиск по вопросу или теме','Search a question or topic')}"><span>${icon('search')}</span></div><div class="help-category-grid">${HELP_ARTICLES.map((r,i)=>`<details class="help-article" data-help-card><summary><span class="help-article-icon">${icon(['cart','wallet','shield','star'][i])}</span><b>${r.title[lang]}</b><span class="profile-menu-arrow">${icon('chevron')}</span></summary><p>${r.body[lang]}</p></details>`).join('')}</div><p id="help-no-results" class="empty" hidden>${adminText('Mos javob topilmadi. Boshqa so‘z bilan qidiring.','Подходящих ответов нет. Попробуйте другой запрос.','No matching answers. Try a different search.')}</p><div class="help-contact-grid"><a class="panel help-contact-card" href="#orders"><b>${adminText('Buyurtma bo‘yicha yordam','Помощь по заказу','Order help')}</b><span>${adminText('Buyurtmani ochib muammo bo‘lsa nizo yuboring.','Откройте заказ и отправьте спор, если возникла проблема.','Open an order and submit a dispute if there is a problem.')}</span></a><a class="panel help-contact-card" href="#messages"><b>${adminText('Xabarlar','Сообщения','Messages')}</b><span>${adminText('Sotuvchi bilan faqat platforma ichida yozishing.','Общайтесь с продавцом только на платформе.','Keep seller conversations on-platform.')}</span></a><a class="panel help-contact-card" href="#policies"><b>${adminText('Qoidalar va maxfiylik','Правила и конфиденциальность','Policies and privacy')}</b><span>${adminText('To‘lov, nizolar va maxfiylik qoidalarini o‘qing.','Читайте правила оплаты, споров и конфиденциальности.','Read payment, dispute, and privacy policies.')}</span></a></div></section>`;$('#help-search')?.addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase();let visible=0;$$('[data-help-card]').forEach(card=>{card.hidden=!!q&&!card.textContent.toLocaleLowerCase().includes(q);if(!card.hidden)visible++});$('#help-no-results').hidden=visible>0})}
const BLOG_POSTS=[
 {slug:'xavfsiz-xarid',category:['XAVFSIZ XARID','БЕЗОПАСНАЯ ПОКУПКА','SAFE BUYING'],title:['O‘yin hisobini sotib olishdan oldin tekshiriladigan 5 narsa','5 вещей, которые нужно проверить перед покупкой игрового аккаунта','5 things to check before buying a game account'],summary:['E’lonni tekshirish, sotuvchi bilan xavfsiz yozishish va yetkazishni qabul qilish bo‘yicha qisqa ro‘yxat.','Короткий список: как проверить объявление, безопасно общаться и принять доставку.','A short checklist for reviewing a listing, messaging safely, and accepting delivery.'],date:'2026-10-04',body:[['Platforma va hudud mosligini tekshiring.','Sotuvchidan faqat e’londa ko‘rsatilgan ma’lumotlarni aniqlashtiring; parol yoki OTP so‘ramang.','To‘lovni platformadagi checkout orqali boshlang.','Yetkazilgan ma’lumotni tekshirib, shundan keyingina buyurtmani yakunlang.','Nizo bo‘lsa, muammoni buyurtma sahifasidan yuboring.'],['Проверьте платформу и регион.','Уточняйте только сведения из объявления; не просите пароль или OTP.','Оформляйте заказ через checkout платформы.','Проверьте доставку и только после этого завершайте заказ.','Если возник спор, сообщите о проблеме на странице заказа.'],['Check platform and region compatibility.','Ask about the listing details; never request a password or OTP.','Start checkout through the marketplace.','Inspect delivery before completing the order.','Open a dispute from the order page if something is wrong.']]},
 {slug:'sotuvchi-qollanma',category:['SOTUVCHI QO‘LLANMASI','РУКОВОДСТВО ПРОДАВЦА','SELLER GUIDE'],title:['Aniq va ishonchli e’lon yozish','Как создать понятное объявление','Writing a clear, trustworthy listing'],summary:['Yaxshi sarlavha, to‘liq tavsif va yetkazish shartlari xaridorga to‘g‘ri qaror qilishga yordam beradi.','Хороший заголовок, полное описание и условия доставки помогают покупателю принять решение.','A clear title, complete description, and delivery terms help buyers make an informed choice.'],date:'2026-10-04',body:[['Sarlavhada o‘yin, platforma va asosiy xususiyatni yozing.','Narxga nimalar kirishini va hudud cheklovlarini ko‘rsating.','Yetkazish muddatini real belgilang.','Boshqa odamning shaxsiy ma’lumotlari yoki ruxsatsiz tasvirlarni joylamang.','Sotishdan oldin email, Didit va moderator tekshiruvi yakunlanishi kerak.'],['Укажите игру, платформу и основные особенности в заголовке.','Объясните, что входит в цену, и укажите ограничения региона.','Установите реалистичный срок доставки.','Не размещайте чужие персональные данные или изображения без разрешения.','Перед продажей нужны подтверждение почты, Didit и модерация.'],['Put the game, platform, and key features in the title.','Explain what the price includes and list region restrictions.','Set a realistic delivery timeframe.','Do not post another person’s personal data or unauthorized images.','Email, Didit, and moderator checks must finish before selling.']]},
 {slug:'aldovlardan-himoya',category:['HISOB XAVFSIZLIGI','ЗАЩИТА ОТ МОШЕННИЧЕСТВА','ACCOUNT SAFETY'],title:['Fishing va soxta yordam xabarlarini tanish','Как распознать фишинг и поддельную поддержку','Spotting phishing and fake support messages'],summary:['Parol, OTP va tiklash havolalari hech qachon sotuvchiga yoki begona “yordamchi”ga berilmaydi.','Пароль, OTP и ссылки восстановления нельзя передавать продавцу или неизвестной «поддержке».','Never give passwords, OTP codes, or reset links to a seller or an unsolicited “support agent.”'],date:'2026-10-04',body:[['Parol va tiklash kodini hech kim bilan bo‘lishmang.','Shubhali havolaga kirmasdan domen nomini tekshiring.','To‘lovni platformadan tashqarida yuborish taklifiga rozi bo‘lmang.','Hisobga kira olmasangiz, faqat rasmiy tiklash oqimidan foydalaning.'],['Не сообщайте пароль и коды восстановления.','Проверяйте домен до перехода по подозрительной ссылке.','Не соглашайтесь переводить деньги вне платформы.','Для восстановления доступа используйте только официальный процесс.'],['Do not share passwords or recovery codes.','Check the domain before opening a suspicious link.','Do not pay outside the marketplace when asked.','Use the official recovery flow if you lose access.']]}
];
function blogCard(post){const i=locale==='ru'?1:locale==='uz'?0:2;return `<article class="blog-card"><span class="blog-category">${post.category[i]}</span><time class="blog-date">${new Date(post.date+'T00:00:00Z').toLocaleDateString(localeTag(),{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'})}</time><h2><a href="#blog/${post.slug}">${post.title[i]}</a></h2><p>${post.summary[i]}</p><a class="text-link" href="#blog/${post.slug}">${adminText('Maqolani o‘qish →','Читать статью →','Read article →')}</a></article>`}
async function renderBlog(){const i=locale==='ru'?1:locale==='uz'?0:2;app.innerHTML=`<section class="page">${pageTitle(adminText('SentryLoot blogi','Блог SentryLoot','SentryLoot blog'),adminText('Xavfsiz xarid, ishonchli savdo va o‘yin bozoriga oid qo‘llanmalar.','Советы по безопасным покупкам, продажам и игровому рынку.','Guides to safer buying, selling, and gaming marketplaces.'))}<div class="blog-feature"><span>${adminText('SENTRYLOOT · QO‘LLANMALAR','SENTRYLOOT · ГИДЫ','SENTRYLOOT · GUIDES')}</span><h2>${BLOG_POSTS[0].title[i]}</h2><p>${BLOG_POSTS[0].summary[i]}</p><a class="button-primary" href="#blog/${BLOG_POSTS[0].slug}">${adminText('O‘qishni boshlash','Начать чтение','Start reading')}</a></div><div class="blog-grid">${BLOG_POSTS.slice(1).map(blogCard).join('')}</div></section>`}
async function renderBlogArticle(slug){const post=BLOG_POSTS.find(x=>x.slug===slug);if(!post){app.innerHTML=`<section class="page">${pageTitle(adminText('Maqola topilmadi','Статья не найдена','Article not found'))}<a class="button-secondary" href="#blog">${adminText('Blogga qaytish','Вернуться в блог','Back to blog')}</a></section>`;return}const i=locale==='ru'?1:locale==='uz'?0:2;app.innerHTML=`<article class="page blog-article"><a class="text-link" href="#blog">← ${adminText('Blogga qaytish','Вернуться в блог','Back to blog')}</a><span class="blog-category">${post.category[i]}</span><time class="blog-date">${new Date(post.date+'T00:00:00Z').toLocaleDateString(localeTag(),{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'})}</time><h1 class="page-title">${post.title[i]}</h1><p class="page-subtitle">${post.summary[i]}</p><div class="blog-article-body">${post.body[i].map((p,n)=>`<p>${n+1}. ${p}</p>`).join('')}</div><div class="notice">${adminText('Ushbu maqolalar umumiy ma’lumot uchun. Har bir e’lon va o‘yin qoidalarini alohida tekshiring.','Статьи носят общий информационный характер. Проверяйте каждое объявление и правила игры отдельно.','These articles are general information. Check each listing and the game’s rules separately.')}</div></article>`}
function adminText(uz,ru,en){return locale==='ru'?ru:locale==='uz'?uz:(window.BOZOR_EXTRA_COPY?.[locale]?.[uz]||en)}
function blogDate(value){const d=new Date(String(value||'').replace(' ','T')+'Z');return Number.isNaN(+d)?'':d.toLocaleDateString(localeTag(),{year:'numeric',month:'long',day:'numeric'})}
function blogCard(post){const i=locale==='ru'?1:locale==='uz'?0:2;return `<article class="blog-card"><span class="blog-category">${esc(post.category[i])}</span><time class="blog-date">${blogDate(post.published_at||post.created_at)}</time><h2><a href="#blog/${encodeURIComponent(post.slug)}">${esc(post.title[i])}</a></h2><p>${esc(post.summary[i])}</p><a class="text-link" href="#blog/${encodeURIComponent(post.slug)}">${adminText('Maqolani o‘qish →','Читать статью →','Read article →')}</a></article>`}
async function renderBlog(){const posts=await api('/blog'),i=locale==='ru'?1:locale==='uz'?0:2;app.innerHTML=`<section class="page">${pageTitle(adminText('SentryLoot blogi','Блог SentryLoot','SentryLoot blog'),adminText('Xavfsiz xarid, ishonchli savdo va o‘yin bozoriga oid qo‘llanmalar.','Советы по безопасным покупкам, продажам и игровому рынку.','Guides to safer buying, selling, and gaming marketplaces.'),me?.is_admin?`<a class="button-secondary" href="#admin-blog">${adminText('Maqolalarni boshqarish','Управление статьями','Manage articles')}</a>`:'')}<div class="blog-feature"><span>SENTRYLOOT · ${adminText('QO‘LLANMALAR','ГИДЫ','GUIDES')}</span><h2>${posts.length?esc(posts[0].title[i]):adminText('Yangi maqolalar tez orada','Новые статьи скоро появятся','New articles coming soon')}</h2><p>${posts.length?esc(posts[0].summary[i]):adminText('Xarid va savdo bo‘yicha foydali qo‘llanmalar shu yerda chiqadi.','Здесь появятся полезные руководства по покупкам и продажам.','Helpful buying and selling guides will appear here.')}</p>${posts.length?`<a class="button-primary" href="#blog/${encodeURIComponent(posts[0].slug)}">${adminText('O‘qishni boshlash','Начать чтение','Start reading')}</a>`:''}</div><div class="blog-grid">${posts.slice(1).map(blogCard).join('')}</div>${posts.length?'':empty(adminText('Hozircha nashr qilingan maqola yo‘q.','Пока нет опубликованных статей.','No published articles yet.'))}</section>`}
async function renderBlogArticle(slug){let post;try{post=await api('/blog/'+encodeURIComponent(slug))}catch{}if(!post){app.innerHTML=`<section class="page">${pageTitle(adminText('Maqola topilmadi','Статья не найдена','Article not found'))}<a class="button-secondary" href="#blog">${adminText('Blogga qaytish','Вернуться в блог','Back to blog')}</a></section>`;return}const i=locale==='ru'?1:locale==='uz'?0:2;app.innerHTML=`<article class="page blog-article"><a class="text-link" href="#blog">← ${adminText('Blogga qaytish','Вернуться в блог','Back to blog')}</a><span class="blog-category">${esc(post.category[i])}</span><time class="blog-date">${blogDate(post.published_at||post.created_at)}</time><h1 class="page-title">${esc(post.title[i])}</h1><p class="page-subtitle">${esc(post.summary[i])}</p><div class="blog-article-body">${post.body[i].map((p,n)=>`<p>${n+1}. ${esc(p)}</p>`).join('')}</div><div class="notice">${adminText('Ushbu maqolalar umumiy ma’lumot uchun. Har bir e’lon va o‘yin qoidalarini alohida tekshiring.','Статьи носят общий информационный характер. Проверяйте каждое объявление и правила игры отдельно.','These articles are general information. Check each listing and the game’s rules separately.')}</div></article>`}
function blogEditor(post={}){const langs=['O‘zbekcha','Русский','English'];const values=['category','title','summary','body'];return `<form id="blog-editor" class="blog-editor-form"><input type="hidden" name="id" value="${esc(post.id||'')}"><div class="field"><label for="blog-slug">URL slug</label><input id="blog-slug" name="slug" value="${esc(post.slug||'')}" pattern="[a-z0-9]+(-[a-z0-9]+)*" required maxlength="80" placeholder="xavfsiz-xarid"></div>${langs.map((lang,i)=>`<fieldset class="blog-language-fields"><legend>${lang}</legend><div class="field"><label>${adminText('Kategoriya','Категория','Category')}</label><input name="category_${i}" required maxlength="60" value="${esc(post.category?.[i]||'')}"></div><div class="field"><label>${adminText('Sarlavha','Заголовок','Title')}</label><input name="title_${i}" required maxlength="140" value="${esc(post.title?.[i]||'')}"></div><div class="field"><label>${adminText('Qisqa mazmun','Краткое описание','Summary')}</label><textarea name="summary_${i}" required maxlength="500" rows="2">${esc(post.summary?.[i]||'')}</textarea></div><div class="field"><label>${adminText('Maqola matni (har paragraf alohida qatorda)','Текст статьи (каждый абзац с новой строки)','Article text (one paragraph per line)')}</label><textarea name="body_${i}" required rows="5">${esc(post.body?.[i]?.join('\n')||'')}</textarea></div></fieldset>`).join('')}<div class="field"><label>${adminText('Holat','Статус','Status')}</label><select name="status"><option value="draft" ${post.status!=='published'?'selected':''}>${adminText('Qoralama','Черновик','Draft')}</option><option value="published" ${post.status==='published'?'selected':''}>${adminText('Nashr qilish','Опубликовано','Published')}</option></select></div><div class="actions"><button class="button-primary">${adminText('Saqlash','Сохранить','Save')}</button><button type="button" class="button-secondary" id="blog-editor-cancel">${adminText('Bekor qilish','Отмена','Cancel')}</button></div></form>`}
async function renderAdminBlog(){if(!me){location.hash='login';return}if(!me.is_admin){app.innerHTML=`<section class="page">${pageTitle(adminText('Maqolalar boshqaruvi','Управление статьями','Article management'))}<div class="notice error">${adminText('Administrator ruxsati kerak.','Требуются права администратора.','Administrator access required.')}</div></section>`;return}const posts=await api('/admin/blog');app.innerHTML=`<section class="page">${pageTitle(adminText('Blog boshqaruvi','Управление блогом','Blog management'),adminText('Uch tildagi maqolalarni yozing, qoralama saqlang yoki saytga nashr qiling.','Пишите статьи на трёх языках, сохраняйте черновики или публикуйте.','Write articles in three languages, save drafts, or publish them.'),`<a class="button-secondary" href="#admin">${adminText('Admin paneliga qaytish','Назад в админ-панель','Back to admin')}</a>`)}<div class="admin-blog-toolbar"><span>${posts.length} ${adminText('maqola','статей','articles')}</span><button class="button-primary" id="blog-new">${adminText('Yangi maqola','Новая статья','New article')}</button><a class="button-secondary" href="#blog">${adminText('Blogni ko‘rish','Открыть блог','View blog')}</a></div><div class="blog-admin-list">${posts.map(p=>`<article class="panel blog-admin-row"><div><span class="blog-category">${esc(p.status)}</span><h2>${esc(p.title[0])}</h2><small>${esc(p.slug)} · ${blogDate(p.updated_at)}</small></div><button class="button-secondary" data-edit-post="${esc(p.id)}">${adminText('Tahrirlash','Редактировать','Edit')}</button></article>`).join('')||empty(adminText('Hali maqola yo‘q. Birinchi maqolani yarating.','Статей пока нет. Создайте первую.','No articles yet. Create your first one.'))}<div id="blog-editor-host"></div></div></section>`;const host=$('#blog-editor-host');const open=post=>{host.innerHTML=blogEditor(post);host.scrollIntoView({behavior:'smooth',block:'start'});$('#blog-editor-cancel')?.addEventListener('click',()=>host.replaceChildren())};$('#blog-new')?.addEventListener('click',()=>open());$$('[data-edit-post]').forEach(btn=>btn.addEventListener('click',()=>open(posts.find(p=>p.id===btn.dataset.editPost))));$('#blog-editor')?.addEventListener('submit',saveBlogEditor)}
async function saveBlogEditor(e){e.preventDefault();const f=e.currentTarget,d=new FormData(f),post={slug:d.get('slug'),status:d.get('status'),category:[],title:[],summary:[],body:[]};for(let i=0;i<3;i++){post.category.push(d.get('category_'+i));post.title.push(d.get('title_'+i));post.summary.push(d.get('summary_'+i));post.body.push(d.get('body_'+i).split(/\r?\n/).map(x=>x.trim()).filter(Boolean))}const id=d.get('id');try{await api('/admin/blog'+(id?'/'+encodeURIComponent(id):''),{method:'POST',body:JSON.stringify(post)});toast(adminText('Maqola saqlandi','Статья сохранена','Article saved'));renderAdminBlog()}catch(x){toast(x.message)}}
function adminState(s){const labels={pending_payment:['To‘lov kutilmoqda','Ожидает оплату','Awaiting payment'],paid:['To‘langan','Оплачен','Paid'],awaiting_delivery:['Yetkazish kutilmoqda','Ожидает выдачу','Awaiting delivery'],delivered:['Yetkazildi','Выдан','Delivered'],completed:['Yakunlandi','Завершён','Completed'],cancelled:['Bekor qilindi','Отменён','Cancelled'],disputed:['Nizoda','Спор','Disputed'],pending_review:['Tekshiruvda','На проверке','In review'],published:['Faol','Активно','Active'],rejected:['Rad etildi','Отклонено','Rejected'],draft:['Qoralama','Черновик','Draft'],paused:['To‘xtatilgan','Приостановлено','Paused'],open:['Ochiq','Открыт','Open'],pending:['Kutilmoqda','Ожидает','Pending'],approved:['Tasdiqlandi','Одобрено','Approved'],paid_out:['To‘landi','Выплачено','Paid out'],reviewing:['Ko‘rib chiqilmoqda','На рассмотрении','Reviewing'],resolved:['Yechilgan','Решён','Resolved'],dismissed:['Yopilgan','Закрыт','Dismissed'],not_started:['Boshlanmagan','Не начата','Not started'],verified:['Tasdiqlangan','Подтверждён','Verified'],unverified:['Tasdiqlanmagan','Не подтверждён','Unverified'],disabled:['O‘chirilgan','Отключён','Disabled'],rejected:['Rad etilgan','Отклонён','Rejected']};return `<span class="status ${esc(s)}">${esc(labels[s]?.[locale==='ru'?1:locale==='uz'?0:2]||s)}</span>`}
function adminDate(value){if(!value)return '—';const date=new Date(String(value).replace(' ','T')+(String(value).endsWith('Z')?'':'Z'));return Number.isNaN(+date)?esc(value):date.toLocaleDateString(localeTag(),{day:'2-digit',month:'short',year:'numeric'})}
function adminChart(rows){const values=new Map((rows||[]).map(x=>[x.day,Number(x.count)||0]));const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setUTCHours(0,0,0,0);d.setUTCDate(d.getUTCDate()-i);const key=d.toISOString().slice(0,10);days.push({key,count:values.get(key)||0,label:d.toLocaleDateString(localeTag(),{weekday:'short',timeZone:'UTC'})})}const max=Math.max(1,...days.map(x=>x.count));return `<div class="admin-chart" role="img" aria-label="${adminText('Oxirgi 7 kunlik buyurtmalar','Заказы за последние 7 дней','Orders for the last 7 days')}">${days.map(d=>`<div class="admin-chart-day"><span class="admin-chart-value">${d.count}</span><div class="admin-chart-track"><i style="height:${(d.count?Math.max(8,Math.round(d.count/max*100)):0)}%"></i></div><span class="admin-chart-label">${esc(d.label)}</span></div>`).join('')}</div>`}
function adminOrdersTable(rows){return rows.length?`<div class="table-wrap admin-table-wrap"><table class="data-table admin-table"><thead><tr><th>${adminText('Buyurtma','Заказ','Order')}</th><th>${adminText('Xaridor','Покупатель','Buyer')}</th><th>${adminText('Jami','Сумма','Total')}</th><th>${adminText('Holat','Статус','Status')}</th><th>${adminText('Sana','Дата','Date')}</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="admin-order-ref">${esc(x.reference||x.id)}</span></td><td>${esc(x.buyer_email)}</td><td>${fmt(x.total_minor,x.currency)}</td><td>${adminState(x.status)}</td><td>${adminDate(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty(adminText('Buyurtmalar hali yo‘q.','Заказов пока нет.','No orders yet.'))}
function adminListingCard(l){const waiting=l.status==='pending_review',ai=l.ai_review;const aiCard=waiting||ai?`<div class="notice ${ai?.risk_level==='high'?'warn':''}" style="margin-top:12px"><b>${adminText('AI tekshiruvi — faqat maslahat','Проверка ИИ — только рекомендация','AI review — advisory only')}</b><div>${ai?.status==='complete'?`${esc(ai.risk_level)} risk · ${esc(ai.confidence)} ishonch`:ai?.status==='not_configured'?'AI kaliti ulanmagan':ai?.status==='unavailable'?'AI tekshiruvi hozir mavjud emas':'Hali tekshirilmagan'}</div>${ai?.summary?`<p>${esc(ai.summary)}</p>`:''}${ai?.findings?.length?`<ul>${ai.findings.map(f=>`<li>${esc(f.explanation)}</li>`).join('')}</ul>`:''}${l.risk_flags?.length?`<small>${adminText('Mahalliy qoidalar belgilari:','Локальные сигналы:','Local rule flags:')} ${l.risk_flags.map(esc).join(', ')}</small>`:''}<div><button class="button-secondary" data-action="ai-review" data-id="${esc(l.id)}">${adminText('AI tekshiruvini yangilash','Повторить проверку ИИ','Run AI review')}</button></div></div>`:'';return `<article class="admin-record"><div class="admin-record-main"><div class="admin-record-kicker">${esc(l.game_name||'GAME')} <span>·</span> ${esc(l.category_name||l.product_type||'Digital')}</div><h3>${esc(l.title)}</h3><p>${esc((l.description||'').slice(0,220))}</p><div class="admin-record-meta"><span>${icon('gamepad')}${esc(l.seller_name||'—')}</span><span>${fmt(l.price_minor,l.currency)}</span><span>${adminDate(l.created_at)}</span></div>${aiCard}</div><div class="admin-record-side">${adminState(l.status)}${waiting?`<div class="admin-record-actions"><button class="button-primary" data-action="moderate" data-id="${esc(l.id)}" data-choice="approve">${adminText('Tasdiqlash','Одобрить','Approve')}</button><button class="button-danger" data-action="moderate" data-id="${esc(l.id)}" data-choice="reject">${adminText('Rad etish','Отклонить','Reject')}</button></div>`:''}</div></article>`}
function adminReportCard(r){return `<article class="admin-record admin-report-record"><div class="admin-record-main"><div class="admin-record-kicker">${esc(r.reason||'report')} <span>·</span> ${adminDate(r.created_at)}</div><h3>${esc(r.reporter_email)}</h3><p>${esc(r.details||'')}</p>${r.evidence_url?`<a class="text-link" href="${esc(r.evidence_url)}" target="_blank" rel="noopener noreferrer">${adminText('Dalilni ochish ↗','Открыть доказательство ↗','Open evidence ↗')}</a>`:''}</div><div class="admin-record-side">${adminState(r.status)}<div class="admin-report-controls"><select id="report-${esc(r.id)}" aria-label="${adminText('Shikoyat holati','Статус жалобы','Report status')}"><option value="reviewing" ${r.status==='reviewing'?'selected':''}>${adminText('Ko‘rib chiqilmoqda','На рассмотрении','Reviewing')}</option><option value="resolved" ${r.status==='resolved'?'selected':''}>${adminText('Yechildi','Решён','Resolved')}</option><option value="dismissed" ${r.status==='dismissed'?'selected':''}>${adminText('Yopildi','Закрыт','Dismissed')}</option></select><input id="resolution-${esc(r.id)}" placeholder="${adminText('Qaror izohi','Комментарий к решению','Resolution note')}" value="${esc(r.resolution||'')}"><button class="button-secondary" data-action="report-update" data-id="${esc(r.id)}">${adminText('Saqlash','Сохранить','Save')}</button></div></div></article>`}
function adminSellerCard(s){return `<article class="admin-record"><div class="admin-record-main"><div class="admin-record-kicker">${adminText('SOTUVCHI TEKSHIRUVI','ПРОВЕРКА ПРОДАВЦА','SELLER REVIEW')} <span>·</span> ${adminDate(s.created_at)}</div><h3>${esc(s.shop_name||s.display_name)} <span class="admin-secondary-name">${esc(s.display_name)}</span></h3><p>${esc(s.bio||adminText('Do‘kon tavsifi berilmagan.','Описание магазина не указано.','No shop description provided.'))}</p><div class="admin-record-meta"><span>${esc(s.email)}</span><span>${adminState(s.verification_status)}</span><span>Didit: ${adminState(s.identity_status||'not_started')}</span><span>${s.selling_enabled?adminText('Savdo yoqilgan','Продажи включены','Selling enabled'):adminText('Savdo o‘chiq','Продажи отключены','Selling disabled')}</span></div><div class="notice warn admin-note">${adminText('Tasdiqlashdan oldin Didit ID, liveness va yuz mosligini tasdiqlashi kerak. Pasport va yuz tasviri admin panelga kelmaydi.','Перед одобрением Didit должен подтвердить документ, liveness и совпадение лица. Фото паспорта и лица не поступают в панель администратора.','Didit must approve the ID, liveness, and face match before seller approval. Passport and face images never enter the admin panel.')}</div></div><div class="admin-record-side">${adminState(s.selling_enabled?s.verification_status:'disabled')}<div class="admin-record-actions"><button class="button-primary" data-action="seller-review" data-id="${esc(s.user_id)}" data-choice="approve" ${(s.identity_status!=='verified'||s.identity_provider!=='didit')?'disabled title="Didit tekshiruvi kerak"':''}>${adminText('Tasdiqlash','Одобрить','Approve')}</button><button class="button-danger" data-action="seller-review" data-id="${esc(s.user_id)}" data-choice="reject">${adminText('Rad etish','Отклонить','Reject')}</button></div></div></article>`}
function adminDisputeCard(d){const canResolve=d.payment_provider==='sandbox'&&d.payment_status==='succeeded',ageHours=Math.max(0,Math.floor((Date.now()-new Date(d.created_at).getTime())/3600000));return `<article class="admin-record"><div class="admin-record-main"><div class="admin-record-kicker">${adminText('NIZO','СПОР','DISPUTE')} <span>·</span> ${adminDate(d.created_at)} <span>·</span> ${adminText(`${ageHours} soat navbatda`,`${ageHours} ч. в очереди`,`${ageHours}h in queue`)}</div><h3>${esc(d.reference)} <span class="admin-secondary-name">${esc(d.buyer_email)}</span></h3><p>${esc(d.details||'')}</p><div class="admin-record-meta"><span>${adminText('Buyurtma','Заказ','Order')}: ${adminState(d.order_status)}</span><span>${fmt(d.total_minor,d.currency)}</span><span>${adminText('Sotuvchi','Продавец','Seller')}: ${esc(d.seller_emails||'—')}</span></div>${!canResolve?`<div class="notice warn admin-note">${adminText('Moliyaviy amal faqat muvaffaqiyatli sandbox to‘lovi uchun ko‘rsatiladi.','Финансовое действие доступно только для успешного sandbox-платежа.','Financial actions are available only for a successful sandbox payment.')}</div>`:''}</div><div class="admin-record-side">${adminState(d.report_status)}<div class="admin-record-actions admin-actions-stack"><button class="button-secondary" data-action="dispute-review" data-id="${esc(d.order_id)}" data-choice="request_info">${adminText('Dalil so‘rash','Запросить доказательства','Request evidence')}</button>${canResolve?`<button class="button-primary" data-action="dispute-review" data-id="${esc(d.order_id)}" data-choice="release_seller">${adminText('Sotuvchiga yechish','В пользу продавца','Release to seller')}</button><button class="button-danger" data-action="dispute-review" data-id="${esc(d.order_id)}" data-choice="refund_buyer">${adminText('Xaridorga qaytarish','Вернуть покупателю','Refund buyer')}</button>`:''}</div></div></article>`}
function adminPayoutCard(p){let actions='';if(p.status==='pending')actions=`<button class="button-primary" data-action="payout" data-id="${esc(p.id)}" data-choice="approve">${adminText('Ma’qullash','Одобрить','Approve')}</button><button class="button-danger" data-action="payout" data-id="${esc(p.id)}" data-choice="reject">${adminText('Rad etish','Отклонить','Reject')}</button>`;else if(p.status==='approved')actions=`<button class="button-primary" data-action="payout" data-id="${esc(p.id)}" data-choice="mark_paid">${adminText('Tashqi o‘tkazmani qayd etish','Записать внешний перевод','Record external transfer')}</button>`;return `<article class="admin-record"><div class="admin-record-main"><div class="admin-record-kicker">${adminText('PAYOUT SO‘ROVI','ЗАПРОС НА ВЫПЛАТУ','PAYOUT REQUEST')} <span>·</span> ${adminDate(p.created_at)}</div><h3>${esc(p.display_name||p.email)} <span class="admin-secondary-name">${fmt(p.amount_minor,p.currency)}</span></h3><p>${esc(p.note||adminText('Izoh yo‘q.','Без комментария.','No note provided.'))}</p><div class="admin-record-meta"><span>${esc(p.email)}</span>${p.external_reference?`<span>${adminText('Tashqi ID','Внешний ID','External ID')}: ${esc(p.external_reference)}</span>`:''}</div></div><div class="admin-record-side">${adminState(p.status)}${actions?`<div class="admin-record-actions">${actions}</div>`:''}</div></article>`}
function adminDeletionCard(d){return `<article class="admin-record admin-compact-record"><div class="admin-record-main"><div class="admin-record-kicker">${adminDate(d.created_at)}</div><h3>${esc(d.display_name||d.email)} <span class="admin-secondary-name">${esc(d.email)}</span></h3><p>${esc(d.reason||adminText('Sabab ko‘rsatilmagan.','Причина не указана.','No reason provided.'))}</p></div><div class="admin-record-side">${adminState(d.status)}<div class="admin-record-actions"><button class="button-secondary" data-action="deletion-review" data-id="${esc(d.id)}" data-choice="reviewing">${adminText('Ko‘rib chiqish','Рассмотреть','Review')}</button><button class="button-secondary" data-action="deletion-review" data-id="${esc(d.id)}" data-choice="resolved">${adminText('Yakunlash','Завершить','Resolve')}</button><button class="button-danger" data-action="deletion-review" data-id="${esc(d.id)}" data-choice="dismissed">${adminText('Yopish','Закрыть','Dismiss')}</button></div></div></article>`}
function adminUserRows(users){return users.length?`<div class="table-wrap admin-table-wrap"><table class="data-table admin-table"><thead><tr><th>${adminText('Foydalanuvchi','Пользователь','User')}</th><th>${adminText('Email holati','Статус email','Email status')}</th><th>${adminText('Ro‘yxatdan o‘tgan','Регистрация','Joined')}</th><th>${adminText('Holat / amal','Статус / действие','Status / action')}</th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.display_name)}</b><small class="admin-cell-sub">${esc(u.email)}</small></td><td>${u.email_verified?adminText('Tasdiqlangan','Подтверждён','Verified'):adminText('Tasdiqlanmagan','Не подтверждён','Unverified')}</td><td>${adminDate(u.created_at)}</td><td><div class="admin-user-action">${u.suspended?`<span class="status rejected">${adminText('Cheklangan','Ограничен','Suspended')}</span>`:`<span class="status published">${adminText('Faol','Активен','Active')}</span>`}<button class="button-secondary" data-action="suspend-user" data-id="${esc(u.id)}" data-choice="${u.suspended?'restore':'suspend'}" ${u.id===me.id?'disabled':''}>${u.id===me.id?adminText('Joriy admin','Текущий администратор','Current admin'):u.suspended?adminText('Qayta yoqish','Восстановить','Restore'):adminText('Cheklash','Ограничить','Suspend')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty(adminText('Foydalanuvchi topilmadi.','Пользователи не найдены.','No users found.'))}
function activateAdminView(name){adminActiveView=name;$$('[data-admin-view]',app).forEach(s=>s.hidden=s.dataset.adminView!==name);$$('[data-admin-view-target]',app).forEach(b=>{const active=b.dataset.adminViewTarget===name;b.classList.toggle('is-active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const title=$(`[data-admin-heading="${name}"]`,app);const h=$('#admin-page-title',app);if(title&&h)h.textContent=title.textContent}
async function renderAdmin(){if(!me){location.hash='login';return}if(!me.is_admin){app.innerHTML=`<section class="page">${pageTitle(adminText('Admin paneli','Панель администратора','Admin panel'))}<div class="notice error">${adminText('Administrator ruxsati yo‘q. Admin hisobini faqat seed.py orqali yarating.','Нет прав администратора. Создайте администратора через seed.py.','Administrator access required. Create an admin account through seed.py.')}</div></section>`;return}const [o,ls,reports,payouts,orders,deletions,sellers,disputes,users]=await Promise.all([api('/admin/overview'),api('/admin/listings'),api('/admin/reports'),api('/admin/payouts'),api('/admin/orders'),api('/admin/deletions'),api('/admin/sellers'),api('/admin/disputes'),api('/admin/users?q=')]);const publicReports=reports.filter(r=>r.reason!=='order_dispute');const mode=String(o.mode||'development').toUpperCase();const daily=o.daily_orders||[];const orderRows=orders.slice(0,100);app.innerHTML=`<section class="admin-portal"><aside class="admin-sidebar"><div class="admin-brand"><span class="admin-brand-mark"><img src="/static/assets/sentryloot-logo-crest.jpg?v=1" alt=""></span><span><b>SENTRY<span>LOOT</span></b><small>${adminText('BOSHQARUV','УПРАВЛЕНИЕ','CONTROL')}</small></span></div><div class="admin-profile"><div class="admin-avatar">${esc((me.display_name||'A').trim().slice(0,1).toUpperCase())}</div><div><b>${esc(me.display_name||'Administrator')}</b><small>${adminText('Administrator','Администратор','Administrator')}</small></div><span class="admin-online-dot"></span></div><nav class="admin-nav" aria-label="${adminText('Admin bo‘limlari','Разделы админ-панели','Admin sections')}"><span class="admin-nav-label">${adminText('ISH STOLI','РАБОЧАЯ ОБЛАСТЬ','WORKSPACE')}</span><button class="admin-nav-item" data-admin-view-target="overview"><span>${icon('gamepad')}<b>${adminText('Umumiy ko‘rinish','Обзор','Overview')}</b></span></button><span class="admin-nav-label">${adminText('BOSHQARUV','УПРАВЛЕНИЕ','MANAGEMENT')}</span><button class="admin-nav-item" data-admin-view-target="listings"><span>${icon('box')}<b>${adminText('E’lonlar','Объявления','Listings')}</b></span>${o.pending_listings?`<i>${o.pending_listings}</i>`:''}</button><button class="admin-nav-item" data-admin-view-target="orders"><span>${icon('cart')}<b>${adminText('Buyurtmalar','Заказы','Orders')}</b></span></button><button class="admin-nav-item" data-admin-view-target="sellers"><span>${icon('shield')}<b>${adminText('Sotuvchilar','Продавцы','Sellers')}</b></span>${sellers.length?`<i>${sellers.length}</i>`:''}</button><span class="admin-nav-label">${adminText('ISHONCH VA MOLIYA','ДОВЕРИЕ И ФИНАНСЫ','TRUST & FINANCE')}</span><button class="admin-nav-item" data-admin-view-target="disputes"><span>${icon('message')}<b>${adminText('Nizolar','Споры','Disputes')}</b></span>${disputes.length?`<i class="is-alert">${disputes.length}</i>`:''}</button><button class="admin-nav-item" data-admin-view-target="reports"><span>${icon('bell')}<b>${adminText('Shikoyatlar','Жалобы','Reports')}</b></span>${o.open_reports?`<i>${o.open_reports}</i>`:''}</button><button class="admin-nav-item" data-admin-view-target="payouts"><span>${icon('arrow-up-right')}<b>${adminText('Payoutlar','Выплаты','Payouts')}</b></span>${o.pending_payouts?`<i>${o.pending_payouts}</i>`:''}</button><span class="admin-nav-label">${adminText('AKKAUNT','АККАУНТ','ACCOUNT')}</span><button class="admin-nav-item" data-admin-view-target="users"><span>${icon('users')}<b>${adminText('Foydalanuvchilar','Пользователи','Users')}</b></span></button><button class="admin-nav-item" data-admin-view-target="settings"><span>${icon('settings')}<b>${adminText('Sozlamalar','Настройки','Settings')}</b></span></button></nav><div class="admin-sidebar-foot"><span class="admin-mode-dot"></span><div><b>${mode}</b><small>${adminText('Server muhiti','Режим сервера','Server environment')}</small></div></div></aside><div class="admin-workspace"><header class="admin-topbar"><div><span class="admin-eyebrow">${adminText('SENTRYLOOT · ADMIN CONSOLE','SENTRYLOOT · АДМИН-ПАНЕЛЬ','SENTRYLOOT · ADMIN CONSOLE')}</span><h1 id="admin-page-title">${adminText('Umumiy ko‘rinish','Обзор','Overview')}</h1><p>${adminText('Do‘kon faoliyatini boshqaring va muhim navbatlarni ko‘rib chiqing.','Управляйте магазином и обрабатывайте важные задачи.','Monitor store activity and review the work queue.')}</p></div><div class="admin-top-actions"><span class="admin-secure-tag">${icon('shield')}${adminText('Xavfsiz sessiya','Защищённая сессия','Secure session')}</span><a class="admin-store-link" href="#home">${adminText('Do‘konni ko‘rish','Открыть магазин','View storefront')} ${icon('arrow-up-right')}</a></div></header><div class="admin-views"><span hidden data-admin-heading="overview">${adminText('Umumiy ko‘rinish','Обзор','Overview')}</span><span hidden data-admin-heading="listings">${adminText('E’lonlar moderatsiyasi','Модерация объявлений','Listing moderation')}</span><span hidden data-admin-heading="orders">${adminText('Buyurtmalar','Заказы','Orders')}</span><span hidden data-admin-heading="sellers">${adminText('Sotuvchilarni tasdiqlash','Проверка продавцов','Seller verification')}</span><span hidden data-admin-heading="disputes">${adminText('Buyurtma nizolari','Споры по заказам','Order disputes')}</span><span hidden data-admin-heading="reports">${adminText('Shikoyatlarni ko‘rib chiqish','Рассмотрение жалоб','Report review')}</span><span hidden data-admin-heading="payouts">${adminText('Payout so‘rovlari','Запросы на выплаты','Payout requests')}</span><span hidden data-admin-heading="users">${adminText('Foydalanuvchilar va xavfsizlik','Пользователи и безопасность','Users & safety')}</span><span hidden data-admin-heading="settings">${adminText('Platforma sozlamalari','Настройки платформы','Platform settings')}</span><section class="admin-view" data-admin-view="overview"><div class="admin-kpis"><article class="admin-kpi"><span class="admin-kpi-icon">${icon('arrow-up-right')}</span><small>${adminText('Bugungi buyurtmalar','Заказы сегодня','Orders today')}</small><b>${o.today_orders}</b><em>${adminText('Joriy kun','Текущий день','Current day')}</em></article><article class="admin-kpi"><span class="admin-kpi-icon is-violet">${icon('shield')}</span><small>${adminText('Yakunlangan buyurtmalar','Завершённые заказы','Completed orders')}</small><b>${o.completed_orders}</b><em>${adminText('Barcha vaqt','За всё время','All time')}</em></article><article class="admin-kpi"><span class="admin-kpi-icon is-blue">${icon('box')}</span><small>${adminText('Faol e’lonlar','Активные объявления','Active listings')}</small><b>${o.active_listings}</b><em>${adminText('Hozir ommada','Сейчас опубликованы','Currently published')}</em></article><article class="admin-kpi"><span class="admin-kpi-icon is-gold">${icon('heart')}</span><small>${adminText('Foydalanuvchilar','Пользователи','Users')}</small><b>${o.users}</b><em>${adminText('Jami akkauntlar','Всего аккаунтов','Total accounts')}</em></article></div><div class="admin-dashboard-grid"><article class="admin-panel admin-activity-panel"><div class="admin-panel-heading"><div><span class="admin-eyebrow">${adminText('FAOLLIK','АКТИВНОСТЬ','ACTIVITY')}</span><h2>${adminText('Buyurtmalar faolligi','Активность заказов','Order activity')}</h2></div><span class="admin-period-tag">${adminText('SO‘NGGI 7 KUN','ПОСЛЕДНИЕ 7 ДНЕЙ','LAST 7 DAYS')}</span></div>${adminChart(daily)}</article><article class="admin-panel admin-queue-panel"><div class="admin-panel-heading"><div><span class="admin-eyebrow">${adminText('ISH NAVBATI','ОЧЕРЕДЬ ЗАДАЧ','WORK QUEUE')}</span><h2>${adminText('E’tibor talab qiladi','Требует внимания','Needs attention')}</h2></div>${icon('clock')}</div><button data-admin-view-target="listings" class="admin-queue-link"><span>${adminText('Tekshiriladigan e’lonlar','Объявления на проверке','Listings to review')}</span><b>${o.pending_listings}</b></button><button data-admin-view-target="sellers" class="admin-queue-link"><span>${adminText('Sotuvchi tasdiqlari','Проверки продавцов','Seller verifications')}</span><b>${o.pending_sellers}</b></button><button data-admin-view-target="disputes" class="admin-queue-link"><span>${adminText('Ochiq nizolar','Открытые споры','Open disputes')}</span><b>${o.open_disputes}</b></button><button data-admin-view-target="reports" class="admin-queue-link"><span>${adminText('Ochiq shikoyatlar','Открытые жалобы','Open reports')}</span><b>${o.open_reports}</b></button><button data-admin-view-target="payouts" class="admin-queue-link"><span>${adminText('Payout navbatida','Ожидают выплаты','Pending payouts')}</span><b>${o.pending_payouts}</b></button></article></div><article class="admin-panel admin-orders-panel"><div class="admin-panel-heading"><div><span class="admin-eyebrow">${adminText('SO‘NGGI FAOLLIK','ПОСЛЕДНЯЯ АКТИВНОСТЬ','LATEST ACTIVITY')}</span><h2>${adminText('So‘nggi buyurtmalar','Последние заказы','Recent orders')}</h2></div><button class="admin-inline-link" data-admin-view-target="orders">${adminText('Barcha buyurtmalar','Все заказы','All orders')} ${icon('arrow-up-right')}</button></div>${adminOrdersTable(orderRows.slice(0,7))}</article><div class="admin-sandbox-banner"><span class="admin-sandbox-icon">${icon('shield')}</span><div><b>${adminText('To‘lovlar sinov muhitida ishlaydi','Платежи работают в тестовом режиме','Payments are in sandbox mode')}</b><p>${adminText('Haqiqiy provayder yoki pul o‘tkazmasi ulanmagan. Payout tasdig‘i tashqi o‘tkazmani avtomatik bajarmaydi.','Реальный платёжный провайдер не подключён. Одобрение выплаты не переводит деньги автоматически.','No live payment provider or transfer is connected. Approving a payout does not move funds.')}</p></div><span class="admin-sandbox-volume"><small>${adminText('SANDBOX TO‘LOV HAJMI','ОБЪЁМ SANDBOX-ПЛАТЕЖЕЙ','SANDBOX PAYMENT VOLUME')}</small><b>${fmt(o.sandbox_volume_minor,'UZS')}</b></span></div></section><section class="admin-view" data-admin-view="listings" hidden><div class="admin-section-intro"><div><h2>${adminText('E’lonlar va moderatsiya','Объявления и модерация','Listings and review')}</h2><p>${adminText('Navbatdagi e’lonlarni tekshiring va faol e’lonlar holatini kuzating.','Проверяйте объявления в очереди и отслеживайте активные.','Review queued listings and inspect active listings.')}</p></div><span class="admin-count-pill">${ls.filter(x=>x.status==='pending_review').length} ${adminText('kutilmoqda','ожидают','pending')}</span></div><div class="admin-record-list">${ls.length?ls.map(adminListingCard).join(''):empty(adminText('Moderatsiya uchun e’lon yo‘q.','Нет объявлений для модерации.','No listings need review.'))}</div></section><section class="admin-view" data-admin-view="orders" hidden><div class="admin-section-intro"><div><h2>${adminText('Barcha buyurtmalar','Все заказы','All orders')}</h2><p>${adminText('Oxirgi 100 ta buyurtma. Har bir holat bazadagi joriy ma’lumotdan olinadi.','Последние 100 заказов. Статусы отражают текущие данные базы.','Latest 100 orders. Statuses reflect current database records.')}</p></div><span class="admin-count-pill">${orders.length} ${adminText('buyurtma','заказов','orders')}</span></div>${adminOrdersTable(orderRows)}</section><section class="admin-view" data-admin-view="sellers" hidden><div class="admin-section-intro"><div><h2>${adminText('Sotuvchi hisoblarini tekshirish','Проверка аккаунтов продавцов','Seller account review')}</h2><p>${adminText('Tasdiqlash yoki rad etish qarori audit jurnaliga yoziladi.','Решения об одобрении и отказе записываются в журнал аудита.','Approval and rejection decisions are recorded in the audit log.')}</p></div><span class="admin-count-pill">${sellers.length} ${adminText('navbatda','в очереди','in queue')}</span></div><div class="admin-record-list">${sellers.length?sellers.map(adminSellerCard).join(''):empty(adminText('Tekshiruv kutayotgan sotuvchi yo‘q.','Нет продавцов, ожидающих проверки.','No sellers are waiting for review.'))}</div></section><section class="admin-view" data-admin-view="disputes" hidden><div class="admin-section-intro"><div><h2>${adminText('Ochiq buyurtma nizolari','Открытые споры по заказам','Open order disputes')}</h2><p>${adminText('Qaror va dalillarni moderator yozuvi bilan saqlang. Pul amallari faqat sandbox’da qayd etiladi.','Сохраняйте решение и доказательства вместе с комментарием модератора. Финансовые действия доступны только в sandbox.','Record decisions with a moderator note. Financial actions are sandbox-only.')}</p></div><span class="admin-count-pill is-alert">${disputes.length} ${adminText('ochiq','открыто','open')}</span></div><div class="admin-record-list">${disputes.length?disputes.map(adminDisputeCard).join(''):empty(adminText('Ochiq nizo yo‘q.','Открытых споров нет.','No open disputes.'))}</div></section><section class="admin-view" data-admin-view="reports" hidden><div class="admin-section-intro"><div><h2>${adminText('Foydalanuvchi shikoyatlari','Жалобы пользователей','User reports')}</h2><p>${adminText('Buyurtma nizolari alohida bo‘limda boshqariladi.','Споры по заказам обрабатываются отдельно.','Order disputes are handled in their own section.')}</p></div><span class="admin-count-pill">${publicReports.length}</span></div><div class="admin-record-list">${publicReports.length?publicReports.map(adminReportCard).join(''):empty(adminText('Shikoyatlar yo‘q.','Жалоб нет.','No reports.'))}</div></section><section class="admin-view" data-admin-view="payouts" hidden><div class="admin-section-intro"><div><h2>${adminText('Sotuvchilarning payout so‘rovlari','Запросы продавцов на выплаты','Seller payout requests')}</h2><p>${adminText('Ma’qullash pulni o‘tkazmaydi. Tashqi provayderda o‘tkazmani bajaring va tasdiq ID sini kiriting.','Одобрение не переводит деньги. Выполните перевод у платёжного провайдера и укажите ID операции.','Approval does not transfer money. Complete the transfer with your provider and enter its reference ID.')}</p></div><span class="admin-count-pill">${payouts.length}</span></div><div class="notice warn admin-global-notice">${adminText('Moliyaviy yozuvlar sandbox hisobidir; haqiqiy mablag‘ ko‘chirilmaydi.','Финансовые записи ведутся в sandbox; реальные средства не переводятся.','Financial records are sandbox-only; no real funds are moved.')}</div><div class="admin-record-list">${payouts.length?payouts.map(adminPayoutCard).join(''):empty(adminText('Payout so‘rovi yo‘q.','Запросов на выплату нет.','No payout requests.'))}</div></section><section class="admin-view" data-admin-view="users" hidden><div class="admin-section-intro"><div><h2>${adminText('Akkauntlarni boshqarish','Управление аккаунтами','Account management')}</h2><p>${adminText('Qidiruv, akkaunt holati va hisobni o‘chirish so‘rovlari.','Поиск, статус аккаунта и запросы на удаление.','Search, account status, and account deletion requests.')}</p></div></div><form id="user-search" class="admin-search-form"><label class="admin-search-box">${icon('search')}<input name="q" aria-label="${adminText('Email yoki ism bo‘yicha qidirish','Поиск по email или имени','Search by email or name')}" placeholder="${adminText('Email yoki ismni kiriting','Введите email или имя','Enter email or name')}"></label><button class="button-primary">${adminText('Qidirish','Найти','Search')}</button></form><div id="user-results" class="admin-user-results">${adminUserRows(users)}</div><div class="admin-subsection-heading"><div><span class="admin-eyebrow">${adminText('MAXFIYLIK SO‘ROVLARI','ЗАПРОСЫ КОНФИДЕНЦИАЛЬНОСТИ','PRIVACY REQUESTS')}</span><h2>${adminText('Hisobni o‘chirish navbati','Очередь удаления аккаунтов','Account deletion queue')}</h2></div><span class="admin-count-pill">${deletions.filter(d=>['pending','reviewing'].includes(d.status)).length}</span></div><div class="admin-record-list">${deletions.length?deletions.map(adminDeletionCard).join(''):empty(adminText('O‘chirish so‘rovlari yo‘q.','Запросов на удаление нет.','No deletion requests.'))}</div></section><section class="admin-view" data-admin-view="settings" hidden><div class="admin-section-intro"><div><h2>${adminText('Platforma sozlamalari','Настройки платформы','Platform settings')}</h2><p>${adminText('Savdo konfiguratsiyasidagi amallar audit jurnaliga yoziladi.','Изменения торговых параметров записываются в журнал аудита.','Changes to commerce settings are recorded in the audit log.')}</p></div></div><div class="admin-settings-grid"><article class="admin-panel admin-setting-card"><span class="admin-setting-icon">${icon('arrow-up-right')}</span><h3>${adminText('Platforma komissiyasi','Комиссия платформы','Platform commission')}</h3><p>${adminText('Yangi buyurtmalarga qo‘llanadigan stavkani belgilang. 100 bps = 1%. Eski buyurtmalardagi stavka o‘zgarmaydi.','Установите ставку для новых заказов. 100 bps = 1%. Ставка существующих заказов не меняется.','Set the rate for new orders. 100 bps = 1%. Existing orders keep their original rate.')}</p><form id="config-form" class="admin-config-form"><label for="commission-bps">${adminText('Komissiya (bazis punkt)','Комиссия (базисные пункты)','Commission (basis points)')}</label><div class="admin-config-input"><input id="commission-bps" name="commission_bps" type="number" min="0" max="3000" step="1" value="${esc(o.config.commission_bps||0)}" required><span>bps</span></div><button class="button-primary">${adminText('Sozlamani saqlash','Сохранить настройку','Save setting')}</button></form><div class="admin-config-footnote">${adminText('Ruxsat etilgan oraliq: 0–3000 bps.','Допустимый диапазон: 0–3000 bps.','Allowed range: 0–3000 bps.')}</div></article><article class="admin-panel admin-setting-card admin-security-card"><span class="admin-setting-icon is-violet">${icon('shield')}</span><h3>${adminText('To‘lovlar va xavfsizlik','Платежи и безопасность','Payments & safety')}</h3><p>${adminText('Joriy muhitdagi savdo va to‘lov holati.','Состояние торговли и платежей в текущей среде.','Commerce and payment status for the current environment.')}</p><div class="admin-security-line"><span>${adminText('Server rejimi','Режим сервера','Server mode')}</span><b>${esc(mode)}</b></div><div class="admin-security-line"><span>${adminText('To‘lov provayderlari','Платёжные провайдеры','Payment providers')}</span><b>${adminText('Sandbox','Sandbox','Sandbox')}</b></div><div class="admin-security-line"><span>${adminText('Audit jurnali','Журнал аудита','Audit log')}</span><b class="admin-enabled">${adminText('Faol','Активен','Active')}</b></div><div class="notice warn">${adminText('Haqiqiy to‘lov provayderi ulanmaguncha tizim real to‘lov yoki payout bajarmaydi.','Пока не подключён реальный платёжный провайдер, система не проводит реальные платежи и выплаты.','The system will not process live payments or payouts until a production provider is configured.')}</div></article></div></section></div></div></section>`;$('#config-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/admin/config',{method:'POST',body:JSON.stringify({commission_bps:Number(new FormData(e.currentTarget).get('commission_bps'))})});toast(adminText('Komissiya yangilandi','Комиссия обновлена','Commission updated'))}catch(x){toast(x.message)}});$('#user-search')?.addEventListener('submit',async e=>{e.preventDefault();try{const q=new URLSearchParams({q:new FormData(e.currentTarget).get('q')});const xs=await api('/admin/users?'+q);$('#user-results').innerHTML=adminUserRows(xs)}catch(x){toast(x.message)}});activateAdminView(adminActiveView)}
function renderGuide(route){
 const title=route==='fees'?adminText('Komissiya va to‘lovlar','Комиссии и платежи','Fees and payments'):route==='policies'?adminText('Foydalanish qoidalari','Правила использования','Terms and policies'):adminText('Xarid va xavfsizlik','Покупки и безопасность','Buying and safety');
 app.innerHTML=`<section class="page">${pageTitle(title)}<div class="legal-copy"><div class="notice warn">${adminText('Bu ma’lumot huquqiy maslahat emas. Xizmat hozircha haqiqiy savdo uchun ochilmagan. Operator, davlatlar, noshir qoidalari, soliq, iste’molchi huquqlari va to‘lov tartibi yurist tomonidan tekshirilmaguncha xarid yoki sotuvga urinmang.','Эта информация не является юридической консультацией. Сервис пока не открыт для реальных продаж. Не покупайте и не продавайте, пока юрист не проверит оператора, страны, правила издателей, налоги, права потребителей и платежи.','This is not legal advice. The service is not open for real sales. Do not buy or sell until counsel reviews the operator, markets, publisher rules, taxes, consumer rights, and payment flow.')}</div><h3>${adminText('Savdo holati','Статус торговли','Sales status')}</h3><p>${adminText('Ishlab chiqarishdagi checkout, real to‘lov, qaytarim va payout hozir yopiq. Sandbox sinovi haqiqiy pulni qabul qilmaydi yoki o‘tkazmaydi. Sotuvchiga tashqi to‘lov qilmang va platforma real escrow yoki xaridor himoyasini ta’minlaydi deb hisoblamang.','Продакшен-checkout, реальные платежи, возвраты и выплаты отключены. Sandbox не принимает и не переводит реальные деньги. Не переводите деньги продавцу вне платформы и не считайте, что платформа обеспечивает реальный escrow или защиту покупателя.','Production checkout, live payments, refunds, and payouts are disabled. Sandbox does not accept or transfer real money. Do not pay a seller off-platform or assume the service provides real escrow or buyer protection.')}</p><h3>${adminText('O‘yin qoidalari va hisoblar','Правила игр и аккаунты','Game rules and accounts')}</h3><p>${adminText('EA shartlari EA akkauntini sotish, ulashish yoki o‘tkazishni ruxsat bermaydi; EA FC Mobile qoidalari ham “mule” akkauntlarini sotib olishga qarshi. PUBG Mobile rasmiy ogohlantirishi akkaunt savdosini ruxsatsiz deb belgilaydi. Shu sabab bu sayt PUBG Mobile va EA FC Mobile akkauntlarini hozircha qabul qilmaydi. Hisobni sotish o‘yin ichida bloklanish xavfini tug‘diradi; bu o‘z-o‘zidan har bir mamlakatda jinoiy jinoyat degani emas — qonuniy oqibatlar joy va vaziyatga qarab farq qiladi.','Условия EA не разрешают продавать, передавать или совместно использовать аккаунт EA; правила FC Mobile также запрещают покупку аккаунтов «mule». Официальное предупреждение PUBG Mobile называет торговлю аккаунтами неразрешённой. Поэтому этот сайт пока не принимает аккаунты PUBG Mobile и EA FC Mobile. Продажа может привести к блокировке в игре; сама по себе она не означает автоматически уголовное преступление во всех странах — правовые последствия зависят от места и обстоятельств.','EA terms prohibit selling, sharing, or transferring an EA Account; FC Mobile rules also prohibit buying “mule” accounts. PUBG Mobile’s official warning describes account trading as unauthorized. This site therefore does not currently accept PUBG Mobile or EA FC Mobile accounts. A sale can risk an in-game ban; that alone does not automatically mean a criminal offense in every country. Legal consequences depend on location and circumstances.')}</p><p><a href="https://www.riotgames.com/en/terms-of-service" target="_blank" rel="noopener noreferrer">Riot Terms of Service</a> · <a href="https://help.steampowered.com/en/faqs/view/71F6-0E69-7C67-E252" target="_blank" rel="noopener noreferrer">Steam account-selling guidance</a></p><h3>${adminText('Akkaunt savdosi uchun platforma qoidalari','Правила площадки для торговли аккаунтами','Marketplace rules for account sales')}</h3><p>${adminText('Sotuvchi: faqat o‘zi egalik qiladigan yoki qonuniy vakolatga ega bo‘lgan, noshir transferga ruxsat bergan akkauntni e’lon qilsin. O‘g‘irlangan, buzib kirilgan, ijaraga olingan, qayta tiklash huquqi boshqa odamda qolgan yoki to‘liq egaligi isbotlanmagan akkauntlar taqiqlanadi. Soxta daraja, inventar yoki egalik da’vosi taqiqlanadi. Xaridor va sotuvchi barcha yozishma hamda yetkazishni platforma ichida qilsin; tashqi to‘lovga o‘tmang. Noshir qoidalari tekshirilmagan o‘yinlar savdosi yopiq qoladi.','Продавец может размещать только принадлежащий ему аккаунт или аккаунт, на передачу которого у него есть полномочия и разрешение издателя. Запрещены украденные, взломанные, арендованные аккаунты, аккаунты с сохранённым доступом для восстановления у третьих лиц и аккаунты без подтверждённого владения. Ложные заявления об уровне, предметах или владельце запрещены. Общайтесь и передавайте заказ только внутри площадки; не соглашайтесь на внешнюю оплату. Игры с непроверенными правилами передачи остаются закрытыми.','Sellers may list only accounts they own or are authorized to transfer where the publisher permits transfer. Stolen, compromised, rented, recoverable by another person, or unverified-ownership accounts are prohibited, as are false claims about rank, inventory, or ownership. Keep all communication and delivery on-platform and never move payment off-site. Account sales stay disabled for games whose publisher rules have not been reviewed.')}</p><p>${adminText('Akkaunt xaridi: o‘yin noshiri akkauntni bloklashi yoki qaytarib olishi mumkin. Saytdagi tekshiruv bu xavfni yo‘q qilmaydi. Xaridni yakunlashdan oldin tavsifni, transfer shartlarini va noshir qoidasini o‘qing. Muammo bo‘lsa, e’lon qilingan muddat ichida buyurtma orqali xabar bering; parol, OTP, tiklash kodi yoki boshqa birovning shaxsiy ma’lumotini dalil sifatida yubormang. Amaldagi qaytarim va nizolar shartlari savdo yoqilishidan oldin operator, yurist va to‘lov provayderi tomonidan tasdiqlanishi shart.','Покупатель: издатель может заблокировать или восстановить аккаунт. Проверка площадки не устраняет этот риск. Перед покупкой прочитайте описание, условия передачи и правила издателя. Сообщите о проблеме через заказ в установленный срок; не отправляйте пароль, OTP, код восстановления или чужие персональные данные. Условия возврата и споров должны быть утверждены оператором, юристом и платёжным провайдером до включения торговли.','Buyers: the publisher may ban or recover an account; marketplace checks cannot remove that risk. Read the listing, transfer terms, and publisher rules before purchase. Report issues through the order within the published window; never submit passwords, OTPs, recovery codes, or another person’s private data as evidence. Refund and dispute terms must be approved by the operator, counsel, and payment provider before sales are enabled.')}</p><p><a href="https://www.ea.com/legal/user-agreement?isLocalized=true target="_blank" rel="noopener noreferrer">EA User Agreement</a> · <a href="https://help.ea.com/en/articles/ea-sports-fc/fc-mobile/rules-fc-mobile/" target="_blank" rel="noopener noreferrer">FC Mobile rules</a> · <a href="https://www.pubgmobile.com/webplat/info/news_version3/35372/57705/57706/57821/57822/57823/m22591/202207/918840.shtml" target="_blank" rel="noopener noreferrer">PUBG Mobile account safety notice</a></p><h3>${adminText('Nizolar va dalillar','Споры и доказательства','Disputes and evidence')}</h3><p>${adminText('Tizimda hozir nizo yuborish shakli va moderator navbati bor, lekin real to‘lov qaytarimi, xavfsiz fayl biriktirish xizmati va e’lon qilingan javob muddati yo‘q. Nizoda parol, OTP, tiklash kodi yoki pasport yubormang. Yordamga murojaat:','Сейчас есть форма спора и очередь модератора, но нет возврата реальных платежей, безопасной загрузки файлов или опубликованного срока ответа. Не отправляйте пароль, OTP, код восстановления или паспорт. Поддержка:','The site has a dispute form and moderator queue, but no live payment refunds, secure evidence upload, or published response deadline. Never send passwords, OTPs, recovery codes, or identity documents. Contact:')} <a href="mailto:compliance@gamestorehub.com">compliance@gamestorehub.com</a>.</p><h3>${adminText('Ruxsat etilmagan materiallar','Запрещённые материалы','Prohibited content')}</h3><p>${adminText('O‘g‘irlangan yoki buzib kirilgan hisoblar, noqonuniy mahsulotlar, fishing, zararli fayllar, shaxsiy ma’lumotlar va noshir qoidalarini buzadigan e’lonlar qabul qilinmaydi. Shubhali holatni moderatorga xabar qiling.','Не допускаются украденные или взломанные аккаунты, незаконные товары, фишинг, вредоносные файлы, персональные данные и объявления, нарушающие правила издателей. Сообщите модератору о подозрительном объявлении.','Stolen or compromised accounts, unlawful goods, phishing, malware, personal data, and listings that violate publisher rules are not allowed. Report suspicious listings to a moderator.')}</p><h3>${adminText('Qaytarish va hisobni qaytarib olish','Возвраты и восстановление аккаунта','Refunds and account recovery')}</h3><p>${adminText('Real savdolar ochilmaganligi sabab hozir e’lon qilingan refund muddati yoki akkaunt qaytarib olingandagi kompensatsiya va’dasi yo‘q. Bunday shartlar yuridik va payment provayder tekshiruvidan so‘ng tasdiqlanmaguncha xizmat xarid/sotuvni ochmaydi.','Поскольку реальные продажи отключены, опубликованного срока возврата или компенсации при восстановлении аккаунта нет. Сервис не откроет торговлю до юридической и платёжной проверки таких условий.','Because live sales are disabled, there is no published refund timeframe or compensation promise for a reclaimed account. Sales remain closed until legal and payment-provider review establishes those terms.')}</p></div></section>`
}

function renderPrivacyPolicy(){app.innerHTML=`<section class="page">${pageTitle('Privacy policy','How SentryLoot collects and uses account information.') }<article class="legal-copy"><p><strong>Effective date: October 7, 2026</strong></p><p>SentryLoot is operated by Asliddinov Shukhratjon. For privacy questions or requests, contact <a href="mailto:compliance@gamestorehub.com">compliance@gamestorehub.com</a>.</p><h3>Information we collect</h3><p>If you sign in with Facebook, Meta provides the information you approve, including your name, profile picture, primary email address, and Facebook account identifier. SentryLoot does not receive your Facebook password. We use this information to create and secure your account, sign you in, and prevent duplicate or fraudulent accounts.</p><p>When you use the marketplace, we also process the account profile information you provide, listings and messages you submit, and records of requests, orders, disputes, and account security events.</p><h3>How information is used and shared</h3><p>We use account information to provide sign-in, marketplace features, customer support, fraud prevention, and dispute handling. Meta processes Facebook Login and returns the fields you approve. Service providers that host and operate SentryLoot may process data on our behalf to run the site and database. When configured, Google Gemini receives only allowlisted, redacted public listing text and basic public game/listing attributes to produce an advisory moderation signal. We do not send seller identity, contact details, listing images, delivery data, dispute evidence, passwords, or verification codes to this AI check. On Gemini's free tier, Google may use submitted prompts and responses to improve its products; do not publish confidential information in a listing. AI suggestions are visible only to moderators and never make account, listing, dispute, or payment decisions. We do not request access to your Facebook friends, posts, or other optional profile information.</p><h3>Retention and deletion</h3><p>We keep account information while the account is active. After we verify an account deletion request, we remove direct profile identifiers, Facebook sign-in links, identity verification data, and user-authored marketplace content within 30 days. We keep completed order and ledger records in an anonymized form where needed for accounting, security, or dispute records. See our <a href="#data-deletion">data deletion instructions</a>.</p><h3>Cookies and security</h3><p>SentryLoot uses a session cookie to keep you signed in and protect account actions. Passwords are stored as password hashes. Facebook access tokens are used server-side to retrieve the approved profile and are not stored as account credentials.</p><h3>Your choices</h3><p>You can update profile details in your account, request account deletion from the account page, or revoke SentryLoot's access in your Facebook settings. Deleting your SentryLoot account does not delete your Facebook account.</p><p>This notice describes the current service. Contact us at <a href="mailto:compliance@gamestorehub.com">compliance@gamestorehub.com</a> with privacy questions.</p></article></section>`}

function renderDataDeletion(){app.innerHTML=`<section class="page">${pageTitle('Data deletion instructions','How to request deletion of SentryLoot account and Facebook Login data.') }<article class="legal-copy"><p>SentryLoot is operated by Asliddinov Shukhratjon. If you used Facebook Login, SentryLoot may hold your Facebook account identifier, name, profile picture, and primary email address.</p><h3>Request deletion while signed in</h3><ol><li>Sign in to SentryLoot and open your Account page.</li><li>Choose <strong>Request account deletion</strong>.</li><li>We verify and review the request, then erase direct account identifiers and Facebook Login data within 30 days.</li></ol><p>When an administrator marks a verified request as resolved, the account is disabled, its Facebook identity and direct profile data are erased, and user-authored content is removed or anonymized. Completed order and ledger records may remain anonymized for accounting, security, or dispute handling.</p><h3>If you cannot access your account</h3><p>Email <a href="mailto:compliance@gamestorehub.com">compliance@gamestorehub.com</a> from the address associated with your account and ask for SentryLoot account and Facebook data deletion. Do not send your Facebook password.</p><p>Deleting SentryLoot data does not delete your Facebook account. You can also remove SentryLoot from the apps and websites connected to your Facebook account.</p><p>Read the full <a href="#privacy-policy">Privacy Policy</a>.</p></article></section>`}
async function doAction(b){const a=b.dataset.action,id=b.dataset.id;try{if(a==='ai-review'){await api('/admin/listings/'+encodeURIComponent(id)+'/ai-review',{method:'POST',body:'{}'});toast('AI tekshiruvi yangilandi');renderAdmin()}else if(a==='link-facebook'){const result=await api('/oauth/start',{method:'POST',body:JSON.stringify({provider:'facebook',mode:'link',country:me?.country||'UZ'})});location.assign(result.authorization_url)}else if(a==='oauth-google'||a==='oauth-facebook'){if(!$('#auth-terms')?.checked){toast('Davom etish uchun shartlarni qabul qiling.');return}const provider=a==='oauth-google'?'google':'facebook';const result=await api('/oauth/start',{method:'POST',body:JSON.stringify({provider,accept_terms:true,country:$('#auth-country')?.value||'UZ'})});location.assign(result.authorization_url)}else if(a==='read-all-notifications'){await api('/notifications/read-all',{method:'POST',body:'{}'});refreshNotifications();await renderNotifications()}else if(a==='mark-notification-read'){await api('/notifications/'+encodeURIComponent(id)+'/read',{method:'POST',body:'{}'});refreshNotifications();await renderNotifications()}else if(a==='open-notification'){await api('/notifications/'+encodeURIComponent(id)+'/read',{method:'POST',body:'{}'});refreshNotifications();location.hash=b.dataset.route||notificationRoute(b.getAttribute('href')?.slice(1))}else if(a==='seller-review'){const note=promptLocale('Sotuvchini tekshirganingiz va qaroringiz sababini kiriting (kamida 5 belgi):');if(!note||note.trim().length<5)return;await api('/admin/sellers/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({action:b.dataset.choice,note})});toast('Sotuvchi holati yangilandi');renderAdmin()}else if(a==='dispute-review'){const action=b.dataset.choice;const label=action==='refund_buyer'?'Sandbox qaytarimini qayd etasizmi? Bu haqiqiy pul o‘tkazmaydi.':action==='release_seller'?'Sotuvchi foydasiga sandbox buyurtmani yakunlayasizmi?':'Moderator qo‘shimcha dalil so‘raydi. Qarorni yozib davom etasizmi?';if(!confirmLocale(label))return;const note=promptLocale('Moderator qarori va dalillarni qisqacha yozing (kamida 5 belgi):');if(!note||note.trim().length<5)return;await api('/admin/disputes/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({action,note})});toast('Nizo holati yangilandi');renderAdmin()}else if(a==='respond-request'){const card=b.closest('.order-line');const form=card?.querySelector('[data-form="request-response"]');if(form){form.hidden=false;b.hidden=true;form.querySelector('textarea')?.focus()}return}else if(a==='cancel-request-response'){const form=b.closest('[data-form="request-response"]');form.hidden=true;const card=b.closest('.order-line');const trigger=card?.querySelector('[data-action="respond-request"]');if(trigger)trigger.hidden=false;return}else if(a==='compare-listing'||a==='compare-remove'){if(a==='compare-remove')comparisonIds=comparisonIds.filter(x=>x!==id);else if(!comparisonIds.includes(id)){if(comparisonIds.length>=3){toast(adminText('Uchta e’longacha tanlash mumkin.','Можно выбрать не более трёх объявлений.','You can compare up to three listings.'));return}comparisonIds.push(id)}localStorage.setItem('sentryloot_compare',JSON.stringify(comparisonIds));location.hash='compare';return}else if(a==='add-cart'){await api('/cart',{method:'POST',body:JSON.stringify({listing_id:id,quantity:1})});toast('Savatchaga qo‘shildi');refreshCart()}else if(a==='favorite'){const x=await api('/favorites/'+id,{method:b.textContent.includes('Saqlangan')?'DELETE':'POST',body:'{}'});toast(x.saved?'Saqlanganlarga qo‘shildi':'Olib tashlandi');navigate()}else if(a==='contact-seller'){const x=await api('/conversations',{method:'POST',body:JSON.stringify({listing_id:id})});location.hash='conversation/'+encodeURIComponent(x.id)}else if(a==='share'){await navigator.clipboard.writeText(location.href);toast('Havola nusxalandi')}else if(a==='remove-cart'){await api('/cart/'+id,{method:'DELETE'});renderCart();refreshCart()}else if(a==='checkout'){if(!$('#checkout-terms')?.checked){toast('Davom etish uchun shartlarni qabul qiling.');return}const accountRisk=$('#checkout-account-risk');if(accountRisk&&!accountRisk.checked){toast('Davom etishdan oldin akkaunt savdosi xavflarini qabul qiling.');return}const x=await api('/checkout',{method:'POST',body:JSON.stringify({accept_terms:true,accept_account_risk:accountRisk?accountRisk.checked:false})});toast('Sandbox buyurtma yaratildi');location.hash='order/'+encodeURIComponent(x.id)}else if(a==='sandbox-pay'){await api('/orders/'+id+'/sandbox-complete',{method:'POST',body:'{}'});toast('Sandbox to‘lov tasdiqlandi');renderOrder(id)}else if(a==='complete-order'){await api('/orders/'+id+'/complete',{method:'POST',body:'{}'});toast('Buyurtma yakunlandi');renderOrder(id)}else if(a==='dispute'){const details=promptLocale('Muammoni qisqacha tushuntiring (kamida 10 belgi):');if(details){const evidence_url=promptLocale('Dalil uchun HTTPS havola (ixtiyoriy). Maxfiy parol yoki shaxsiy ma’lumot joylamang:')||'';await api('/orders/'+id+'/dispute',{method:'POST',body:JSON.stringify({details,evidence_url})});toast('Nizo moderatorga yuborildi');renderOrder(id)}}else if(a==='logout'){await api('/logout',{method:'POST',body:'{}'});me=null;csrf='';toast('Tizimdan chiqdingiz');location.hash='home';bootstrap()}else if(a==='resend-verification'){const x=await api('/verification/resend',{method:'POST',body:JSON.stringify({email:b.dataset.email||''})});$('#auth-message').innerHTML=`<div class="notice">${esc(x.message)}${x.verification_token?`<div class="field" style="margin-top:12px"><label>Development tasdiqlash tokeni</label><input id="verify-token" value="${esc(x.verification_token)}" readonly><button type="button" class="button-secondary" data-action="verify">Emailni tasdiqlash</button></div>`:''}</div>`}else if(a==='verify'){const token=$('#verify-token')?.value;if(!token)return;const x=await api('/verify',{method:'POST',body:JSON.stringify({token})});me=x.user;csrf=x.csrf;toast('Email tasdiqlandi');location.hash='account';bootstrap()}else if(a==='delete-account'){const reason=promptLocale('Hisobni o‘chirish so‘roviga izoh (ixtiyoriy):')||'';const x=await api('/account/deletion-request',{method:'POST',body:JSON.stringify({reason})});toast('Hisob o‘chirish so‘rovi yuborildi: '+x.status)}else if(a==='deletion-review'){await api('/admin/deletions/'+id,{method:'POST',body:JSON.stringify({action:b.dataset.choice})});toast('O‘chirish so‘rovi yangilandi');renderAdmin()}else if(a==='suspend-user'){const reason=promptLocale('Amal sababini kiriting:');if(!reason)return;await api('/admin/users/'+id,{method:'POST',body:JSON.stringify({action:b.dataset.choice,reason})});toast('Hisob holati yangilandi');renderAdmin()}else if(a==='moderate'){if(!confirmLocale(b.dataset.choice==='approve'?'E’lonni ommaga chiqarasizmi?':'E’lonni rad etasizmi?'))return;const note=promptLocale('Moderator izohi:')||'';await api('/admin/listings/'+id,{method:'POST',body:JSON.stringify({action:b.dataset.choice,note})});toast('E’lon holati yangilandi');renderAdmin()}else if(a==='report-update'){const status=$('#report-'+id).value,resolution=$('#resolution-'+id).value;await api('/admin/reports/'+id,{method:'POST',body:JSON.stringify({status,resolution})});toast('Shikoyat yangilandi');renderAdmin()}else if(a==='payout'){const choice=b.dataset.choice;if(choice==='mark_paid'){const external_reference=promptLocale('Tashqi to‘lov provayderi bergan o‘tkazma ID sini kiriting:');if(!external_reference||external_reference.trim().length<3)return;await api('/admin/payouts/'+id,{method:'POST',body:JSON.stringify({action:choice,external_reference})})}else{if(!confirmLocale(choice==='approve'?'So‘rovni ma’qullaysizmi? Pulni provayderda alohida o‘tkazing.':'Payout so‘rovini rad etasizmi?'))return;const note=promptLocale('Izoh (ixtiyoriy):')||'';await api('/admin/payouts/'+id,{method:'POST',body:JSON.stringify({action:choice,note})})}toast('Payout so‘rovi yangilandi');renderAdmin()}else if(a==='submit-listing'){await api('/listings/'+id+'/submit',{method:'POST',body:'{}'});location.hash='listing-review/'+encodeURIComponent(id)}else if(a==='pause-listing'){await api('/listings/'+id+'/state',{method:'POST',body:JSON.stringify({action:'pause'})});toast('E’lon vaqtincha yashirildi');renderSeller()}else if(a==='resume-listing'){await api('/listings/'+id+'/state',{method:'POST',body:JSON.stringify({action:'reopen'})});location.hash='listing-review/'+encodeURIComponent(id)}else if(a==='archive-listing'){if(confirmLocale('E’lonni arxivlaysizmi?')){await api('/listings/'+id+'/state',{method:'POST',body:JSON.stringify({action:'archive'})});toast('E’lon arxivlandi');renderSeller()}}else if(a==='report-listing'){if(!me){location.hash='login';return}const details=promptLocale('Nima uchun xabar bermoqchisiz?');if(details)await api('/reports',{method:'POST',body:JSON.stringify({listing_id:id,reason:'suspicious_listing',details})});toast('Moderatorga yuborildi')}else if(a==='contact-request'){const x=await api('/conversations',{method:'POST',body:JSON.stringify({request_id:id,seller_id:b.dataset.seller})});location.hash='conversation/'+encodeURIComponent(x.id)}}catch(e){toast(e.message)}finally{refreshNotifications()}}
