document.addEventListener('keydown',e=>{const box=e.target.closest('[data-sort-select], [data-category-select]');if(!box)return;const category=box.matches('[data-category-select]'),toggle=category?$('[data-category-toggle]',box):$('[data-sort-toggle]',box),menu=$('.sort-menu',box),options=$$('[role="option"]',box),isOpen=toggle.getAttribute('aria-expanded')==='true';if(e.key==='Escape'&&isOpen){toggle.setAttribute('aria-expanded','false');menu.hidden=true;toggle.focus();e.preventDefault();return}if(e.target===toggle&&(e.key==='ArrowDown'||e.key==='ArrowUp')){toggle.setAttribute('aria-expanded','true');menu.hidden=false;(options.find(option=>option.getAttribute('aria-selected')==='true')||options[0])?.focus();e.preventDefault();return}if(e.target.matches('[role="option"]')){const index=options.indexOf(e.target);if(e.key==='ArrowDown'||e.key==='ArrowUp'||e.key==='Home'||e.key==='End'){const next=e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[next]?.focus();e.preventDefault()}}});
app.addEventListener('click',e=>{const nav=e.target.closest('[data-admin-view-target]');if(nav){e.preventDefault();activateAdminView(nav.dataset.adminViewTarget);return}const b=e.target.closest('[data-action]');if(b){e.preventDefault();doAction(b)}});
app.addEventListener('submit',async e=>{const form=e.target;if(form.dataset.form==='request-response'){e.preventDefault();try{await api('/requests/'+encodeURIComponent(form.dataset.request)+'/respond',{method:'POST',body:JSON.stringify({message:new FormData(form).get('message')})});toast('Javob yuborildi');await renderRequests()}catch(x){toast(x.message)}}else if(form.id==='seller-form'){e.preventDefault();try{await api('/seller',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});const x=await api('/me');me=x.user;csrf=x.csrf;toast(adminText('Sotuvchi profili yaratildi','Профиль продавца создан','Seller profile created'));renderSeller()}catch(x){toast(x.message)}}else if(form.dataset.form==='edit-listing'){e.preventDefault();const formData=new FormData(form),d=Object.fromEntries(formData);d.images=formData.getAll('images').map(x=>String(x).trim()).filter(Boolean);d.linked_accounts=formData.getAll('linked_accounts');d.price_minor=Number(d.price_minor);d.stock=Number(d.stock);d.attributes={rank:d.rank};delete d.rank;for(const [key,value] of formData.entries())if(key.startsWith('game_attr_')&&String(value).trim())d.attributes[key.slice(10)]=String(value).trim();try{await api('/listings/'+encodeURIComponent(form.dataset.id),{method:'PATCH',body:JSON.stringify(d)});toast('E’lon saqlandi; kerak bo‘lsa moderator qayta tekshiradi');await renderSeller()}catch(x){toast(x.message)}}else if(form.dataset.form==='deliver'){e.preventDefault();try{await api('/orders/'+form.dataset.order+'/deliver',{method:'POST',body:JSON.stringify({item_id:form.dataset.item,delivery:new FormData(form).get('delivery')})});toast('Yetkazish yuborildi');renderOrder(form.dataset.order)}catch(x){toast(x.message)}}else if(form.dataset.form==='review'){e.preventDefault();try{await api('/reviews',{method:'POST',body:JSON.stringify({item_id:form.dataset.item,rating:Number(new FormData(form).get('rating')),body:new FormData(form).get('body')})});toast('Sharh saqlandi');form.remove()}catch(x){toast(x.message)}}});
document.addEventListener('submit',e=>{const form=e.target;if(form.id!=='browse-search-form')return;e.preventDefault();queryState={q:new FormData(form).get('q')};location.hash='browse'});
function syncLanguageMenu(){const menu=$('#language-menu'),toggle=$('#language-toggle');if(!menu||!toggle)return;toggle.setAttribute('aria-expanded',String(!menu.hidden));menu.querySelectorAll('[data-language]').forEach(item=>item.setAttribute('aria-checked',String(item.dataset.language===locale)))}
function closeLanguageMenu(){const menu=$('#language-menu');if(menu)menu.hidden=true;syncLanguageMenu()}
async function setLanguage(language){if(!supportedLocales.has(language))return;locale=language;localStorage.setItem(localeKey,locale);document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';syncLanguageMenu();syncSellItemButton();closeLanguageMenu();syncAdminLink();if(me){try{const x=await api('/profile',{method:'POST',body:JSON.stringify({language:locale})});me=x.user;syncProfileTrigger()}catch(err){toast(err.message)}}localizeDOM();await navigate();localizeDOM()}
$('#language-toggle').onclick=()=>{const menu=$('#language-menu');menu.hidden=!menu.hidden;syncLanguageMenu();if(!menu.hidden)menu.querySelector(`[data-language="${locale}"]`)?.focus()};$('#language-menu').addEventListener('click',e=>{const option=e.target.closest('[data-language]');if(option)setLanguage(option.dataset.language)});document.addEventListener('click',e=>{if(!e.target.closest('.language-control'))closeLanguageMenu()});
$('#account-button').addEventListener('click',()=>{if(!me){location.hash='login';return}if($('#profile-dropdown'))closeProfileMenu();else openProfileMenu()});document.body.addEventListener('click',e=>{const a=e.target.closest('[data-go]');if(a)location.hash=a.dataset.go});const profileRoot=$('#profile-menu-root');profileRoot.addEventListener('click',e=>{if(e.target.closest('[data-profile-close]')){closeProfileMenu();return}const action=e.target.closest('[data-action]');if(action){e.preventDefault();doAction(action)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#profile-dropdown')){closeProfileMenu();$('#account-button')?.focus()}});
window.addEventListener('hashchange',()=>{closeProfileMenu();navigate().then(()=>localizeDOM());refreshNotifications()});
document.addEventListener('submit',async e=>{if(e.target.id==='profile-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const x=await api('/profile',{method:'POST',body:JSON.stringify(d)});me=x.user;locale=me.language||locale;localStorage.setItem(localeKey,locale);document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';syncLanguageMenu();syncSellItemButton();syncProfileTrigger();toast('Profil yangilandi');if($('#profile-dropdown'))openProfileMenu();else await navigate()}catch(x){toast(x.message)}}});
